window.HB_TR["romans"]["ks"]=["1. یُس عیسیٰ مسیح سُند خادم اوس، یُس بُلاونہٕ آمُت چُھ، یُس خدایہ سٕنزِ انجیل سٍتـ̡ الگ گومُت،\n2. (یُس تمو امہ برونہہ پننین پیغمبرن مقدس صحیفس منز وعدہ کورمُت اوس۔)\n3. پننِس نیچوِس عیسیٰ مسیح سٕندِس متعلق، یُس داؤد سٕندِ بیول سٍتـ̡ بنیومُت چُھ، یُس مازٕ مُطٲبق اوس بنیومُت۔\n4. تہٕ دِیُن خدایہِ سُند نیٚچُو، پاکیزگی ہٕندِ روحہٕ مطٲبق، مُردٕ سٕندِ دُبارٕ قیامتس سٍتـ̡ {اعلان کرنہٕ: Gr. detrimined}\n5. ییمہِ سٍتـ̡ اسہِ فضل تہٕ رسولی حٲصل سپٕز، سارنٕے قومن مَنٛز ایمان ہٕنزِ فرمانبردٲری خٲطرٕ، تٔمۍ سٕندِس ناوٕ خٲطرٕ: {فرمانبردٲری خٲطرٕ...: یا، ایمانہٕ سٕنزِ فرمانبرداری}\n6. یِمَن مَنٛز چھُ یِمو عیسیٰ مسیح سٕندِ بُلاونہٕ آمُت تہِ:\n7. رومس مَنٛز یُس خدایہِ سٕندِ محبوب سٍتـ̡ بُلاونہٕ آمُت چُھ، یُس مُقدِس سٍتـ̡ بُلاونہٕ آمُت چُھہ: تُہٕندِ خٲطرٕ فضل تہٕ سٍتـ̡ سٍتـ̡ خدایہِ سٕندِ سٍتـ̡ سٍتـ̡ امن تہٕ امن سٍتـ̡ خدایہِ س\n8. گۅڈٕ چُھس بہٕ عیسیٰ مسیح سٕندِ ذریعہٕ پننِس خدایہِ سُند شُکر ادا کران زِ تُہند ایمان چُھ سٲرِسٕے دُنیاہس مُتلق کتھ کرنہٕ یِوان۔\n9. یێمہِ سٍتـ̡ خدا چُھہ میٲنۍ گواہ، یێمِس سٍتـ̡ بہٕ پننِس نیچوِس سٕنزِ انجیل مَنٛز پننہِ روحہٕ سٍتـ̡ خدمت کران چُھس، یێلہِ بہٕ چُھس پننین دعاہن مَنٛز ہمیشہ تُہند ذِکر کران۔ {سۭتۍ: یا، منز}\n10.\\tدرخواست کٔرِتھ، اگر وۅنۍ کُنہِ تہِ طریٖقہٕ سٍتـ̡ بہٕ خدایہ سٕنزِ مرضی سٍتـ̡ ژے نِش یِنُک خۄشحال سفر کٔرِتھ۔\n11. بہٕ چُھس ژے وُچھنُک خواہش، یُتھ بہٕ ژے کانہہ روٝحٲنی تحفہٕ دِتھ، یُس تۅہہ قایم سپدِ۔\n12.\\tیعنی، یُتھ زِ بہٕ گژھہِ ژے سٍتـ̡ رٔلِتھ تہٕ میہ دۅشوے باہمی اعتقاد سٍتـ̡ تسلی دِنہٕ۔ {سۭتۍ: یا، منز}\n13. وۅنۍ بہٕ چُھس نہٕ ژےٚ جہالت کرُن، بھائیو، زِ بہٕ چُھس اکثر چانہِ نِش یِنُک ارادٕ تھاوان، (مگر وُنہِ تام اوسُس دِنہٕ آمُت،) تاکہ بہٕ ہێکہِ تہٕ یێلہِ تہٕ یێلہِ تہٕ باقٕے غیر قومن مَنٛز تہِ میلہِ۔ {among: or, in}\n14. بہٕ چُھس یونانین تہٕ وحشین دۄشوٕنی ہُند مقروض۔ دانشمندن تہٕ نادانن دۄشوٕنی خٲطرٕ۔\n15.\\tتێلہِ یوتاہ میہ مَنٛز چُھ، بہٕ چُھس تۅہہِ تام انجیل تبلیغ کرنہٕ خٲطرٕ تیار، یُس رومس مَنٛز تہِ چُھ۔\n16. کیازِ بہٕ چُھس نہٕ مسیح سٕنزِ انجیل سٍتـ̡ شرمندہ گژھان: کیازِ یہِ چُھہ خدایہِ سٕنز طاقت یُس پریتھ کُنہِ ایمانس سٍتـ̡ نجات دِنـ̡ چُھہ ۔ گوڈٕ یہودی تہٕ یونانین تہِ۔\n17. یێلہِ چُھہ اَتھ مَنٛز خدایہِ سٕنز نیکی ایمانہٕ پى۪ٹھٕ پٲٹھـ̡ ظٲہر سپدان یێلہِ چُھہ یێلہِ یہِ لیکھنہٕ آمُت چُھ، عادل روزِ ایمانہٕ سٍتـ̡ زندٕ۔\n18.\\tیِکیازِ خدایہِ سُند غضب چُھ اسمانہٕ سٍتـ̡ انسانن ہٕنزِ سارِنٕے بے دینی تہٕ بددیانتی سٍتـ̡ ظٲہر سپدان یُس حقیقتس سٍتـ̡ رٔٹِتھ چُھہ ۔\n19.\\tکیازِ یُس خدایہ سٍتـ̡ زانان آسہِ سُہ چُھ تِمن مَنٛز ظٲہر سپدان۔ تکیازِ خداین چھہ تمن ہٲومُت۔ {تمن منز: یا، تمن تام}\n20.\\tتکیازِ دنیاہٕچ تخلیقہٕ سٍتـ̡ چِھہ تٔمِس سٕندِ پوشیدہ چیزن سٍتـ̡ سمجِنہٕ یِوان، یێمہِ سٍتـ̡ تٔمۍ سٕنزِ ابدی قوت تہٕ خدایہِ سٍتـ̡ تہ تِم چھِ نہٕ بہانہ ورٲے آسُن: {توتہ...: یا، تِم آسن}\n21.\\tکیازِ ییلہ تم خدایہ زانان ٲسۍ، تمو کٔر نہ خدایہ سٕندِ سٍتـ̡ تسُند جلال تہٕ نہ ٲسۍ شکر گزار۔ مگر تِمن ہٕندِس تخیلس منز گٔیہِ بیکار، تہٕ تِہُند بیوقوف دِل گٔیہِ گٔیہِ۔\n22.\\tعقلمند آسنُک دعویٰ کٔرِتھ بنییہِ تِم بیوقوف،\n23.\\tتہٕ بدلٲوُن بے عیب خدایہ سُند جلال یُس بد کار انسانس تہٕ جاناوارن، ژۅن قدمن ہٕندِس پٲٹھۍ، تہٕ ژۅن قدمن ہٕندِس پٲٹھۍ۔\n24. تێمہِ مۅکھہ دیت خداین تہِ پننین دلن ہنزن خواہشاتن سٍتـ̡ ناپاکی سٍتـ̡ تہٕ پننین جسمن ہٕنزِ بے عزتی کرنہٕ خٲطرٕ:\n25. یٔمۍ خدایہِ سٕنز حقیقتس اپزس مَنٛز بدلٲوِتھ تہٕ مخلوقہٕ سٕنز عبادت کٔرٕن تہٕ خدمت کٔرٕن، یُس ہمیشہٕ خٲطرٕ بابرکت چُھ۔ آمین۔ {مزید: یا، بلکہ}\n26. اَمہ مۅکھہٕ دِژ خداین تِم ناپاک محبتن ہٕندِس سٍتـ̡ ، تِکیازِ تِہٕنزِ زنانہٕ تہِ کٔر فطرتس خلاف فطرتس مَنٛز فطری استعمال۔\n27.\\tتہٕ یِتھے پٲٹھۍ گٔیہِ مرد زنانہِ ہُند فطری استعمال ترٲوِتھ اکھ أکِس کُن ہوس سٍتۍ دزان۔ مرد چھہِ انسان سٍتۍ سۅ کٲم کران یُس نامناسب چھہ، تہ پانس منز چھہ پننہِ غلطی ہند معاوضہ میلان۔\n28. تہٕ یێلہِ زن تِم خدایہ سٕندِس علمس مَنٛز تھاوُن پسند کران ٲسۍ، خداین دِژ تِم کامہِ کرنہٕ خٲطرٕ یِم نہٕ آسان چھِ۔ {برقرار تھاونہٕ خٲطرٕ: یا، تسلیم کرنہٕ خٲطرٕ} {اکھ مذموم...: یا، اکھ ذہن یُس فیصلہٕ نِش خالی چُھ یا، اکھ ناپسندیدٕ ذہن}\n29.\\tسارِنٕے ناانصافی، زناکاری، بدکاری، لالچ، بدنیتی سٍتـ̡ بٔرِتھ گژھُن۔ حسد، قتل، بحث، دھوکہ، بدنیتی سۭتۍ بٔرتھ۔ سرگوشی کرن والۍ،\n30. غیبت کرَن وٲلۍ، خدایہ سٕندِ نفرت، حقارت، مغرور، شیخی کرَن وٲلۍ، بد چیزن ہٕندِ ایجاد کَرن وٲلۍ، مٲلِس ماجہ ہٕنز نافرمانی،\n31.\\tسمجھنہ ورٲے عہد پھُٹراوُن، فطری محبتہ ورٲے ، بے رحمی، بے رحمی: {فطری ورٲے...: یا غیر ملنسار}\n32.\\tیُس خدایہ سُند فیصلہٕ زانان چُھ، یِم یِم یِتھٕ کامہِ کٔرِتھ چھِ موتُک لایق آسان، تِم چھِ نہ صرف یۅہے کران بلکہ چھِ تِمن سٍتـ̡ خوش سپدان یُس تِمن سٍتـ̡ کران چُھ۔ {have...: یا، رضامندی سٍت}","1.\\tتێلہِ چُھہ تۅہہ ناقابلِ معافی ، اے انسان، یُس تہِ تہِ فیصلہ کرن وول چھُ، تێلہِ تہِ چُھہ پانس مذمت کران۔ تکیازِ یُس فیصلہ کرن وول چھہ یۅہے کٲم کران۔\n2. مگر اسہِ چُھ یقین زِ خدایہ سُند فیصلہ چُھ تِمن خلاف حقیقتس مطٲبق یِم یِتھٕ کامہِ ہُند ارتکاب کران چھِ۔\n3. تہٕ کیا تُہۍ چُھہ یہِ سوچان زِ اے انسان، یُس یِتھۍ کٲم کران چُھ، تہٕ یِتھۍ کٲم کران چُھ، تہٕ یِمن ہُند فیصلہ چُھ کران، زِ توے گژھہِ خدایہ سٕندِس فیصلہٕ نِش بچِتھ؟\n4. یا چھکھ تٔمۍ سٕنزِ نیکی تہٕ بردباری تہٕ زیچھرٕچ دولت نِش حقارت کٔرِتھ۔ یہ نہ زانِتھ زِ خدایہِ سٕنز نیکی چھے توبہٕ کُن واتناوان؟\n5.\\tمگر پننہِ سختی تہٕ بے عیب دِل کٔرِو پانس سٍتـ̡ قہر تہٕ خدایہ سٕندِ نیک فیصلہٕ کِس ظٲہرس سٍتـ̡ پانس سٍتـ̡ قہر ہُند خزانہٕ۔\n6.\\tیُس پریتھ انسان سندس اعمال مطابق ادا کرِ:\n7. تِمن خٲطرٕ یِم صبرٕ سٍتـ̡ نیک کامہِ سٍتـ̡ جلال تہٕ عزت تہٕ لافانی زندگی ژھاران چھِ:\n8.\\tمگر تِمن ہٕندِ خٲطرٕ یِم اختلاف کران چھِ، تہٕ حقیقتٕچ اطاعت کران چھِ، بلکہ چھِ ناپاکیزگی، غصہٕ تہٕ غضبٕچ فرمانبرداری،\n9. بدکار سپدن وٲلِس انسانس سٕندِس پریتھ روحس سٍتـ̡ یُس یہودی سُند تہٕ غیر قومن ہٕندِس سٍتـ̡ بدکار سپدان چُھ، تہٕ یہودی سٕندِس سٍتـ̡ تہٕ بد کار سپدُن۔ {غیر قومی: Gr. Greek}\n10.\\tمگر جلال ، عزت تہٕ امن، پریتھ کٲنسہِ انسانس یُس نیکی کٲم کران چُھ، یہودی سٕندِ خٲطرٕ تہٕ غیر قومن ہٕندِ خٲطرٕ: {غیر قومی: Gr. Greek}\n11.\\tکیازِ خدایہ سٍتـ̡ چُھہ نہ انسانس سٍتـ̡ کانہہ احترام آسان۔\n12.\\tیێلہِ شریعت ورٲے گۅناہ آسہِ تہِ سپدِ تہٕ یێلہِ شریعت سٍتـ̡ گۅنہٕ آسہِ تِمن ہُند فیصلہ ییہِ شریعت سٍتـ̡ کرنہٕ۔\n13. (شریعت ہٕندِس بوزن وٲلِس چُھنہٕ خدایہِ سٕندِس برونہہ کُن، بٔلکہِ شریعت کَرن وٲلِس گژھہِ انصاف کرنہٕ یُن۔\n14.\\tیێلہِ یێلہِ غیر قومی، یێلہِ شریعت چُھہ نہٕ فطرتس سٍتـ̡ شریعت سٍتـ̡ دِنہٕ آمٕتـ̡ شریعت سٍتـ̡ چُھہ یِمن ہٕندِ خٲطرٕ شریعت آسان چُھ، یێلہِ چُھہ شریعت سٍتـ̡ شریعت آسان چُھہ، یێلہِ چُھہ شریعت سٍتـ\n15.\\tیُس شریعت ہٕنز کٲم تہندِس دلس منز لیکھِتھ چھُ، تِہند ضمیر تہِ گواہ دِوان چھُ، تہٕ اَکھ أکِس پیٹھ الزام لگاوان یا نتہٕ معافی دِنہٕ وِزِ تِمن ہٕندِس خیالاتس سٍتـ̡ ظٲہر سپدان چھُ۔) {تہند ضمیر...: یا، ضمیر یُس تمن سٍتۍ گواہ چُھ} {مطلب...: یا، پانس درمیان}\n16. ییمہِ دۅہہٕ خدا میانہِ انجیل مُطٲبق عیسیٰ مسیح سٕندِ ذریعہٕ انسانن ہٕندِس رازن ہُند فیصلہ کرِ۔\n17.\\tوُچھو، ژے چُھہ یہودی وننہٕ آمُت، تہٕ شریعت کٔرِو تہٕ خدایہِ سٕندِس سٍتـ̡ فخر کٔرِو،\n18.\\tتہٕ سُہ چُھہ وصیت زانان تہٕ تِمن چیزن ہٕنز منظوری دِوان یِم شریعت نِش ہدایت دِنہٕ آمٕژ چھِ۔ {منظور...: یا، تمن چیزن ہنز کوشش یم مختلف چِھ}\n19. تہٕ چُھہ یقین زِ تہٕ چُھکھ پان اَنٮ۪ن ہُند رہنُما، تِمن ہُند گاش یُس انہِ گٹہِ منز چُھ،\n20.\\tبیوقوفن ہُند ہیچھناوُن، بچن ہُند استاد، یُس شریعت منز علمٕچ تہٕ حقیقتٕچ شکل آسہِ۔\n21. تَمہِ کِنۍ یُس بییِس ہیچھناوان چُھ، تُہۍ چھُکھ نہٕ پانَس ہیچھناوان؟ یُس انسان تبلیغ کران چھُ، ژیہ ژوٗرِ نِنۍ؟\n22. یُس ژیہ ونان چھہِ زنا کرُن زنا کرُن، کیا ژیہ چھکھ زنا کران؟ یُس بُتن سٍتـ̡ نفرت کران چُھہ، کیا تُہۍ چھِو بے حرمتی کٔرِتھ؟\n23. یُس شریعت ہٕندِس پٲٹھـ̡ پَنُن فخر کران چُھ، شریعت پھٕٹرٲوِتھ چُھہ تہٕ چُھہ خدایہ سٕنز بے عزتی کٔرِتھ؟\n24. یِتھ کٔنۍ چُھہ خدایہِ سُند ناو توے سٍتـ̡ غیر قومن مَنٛز کفر کرنہٕ آمُت، یێلہِ زن یہِ لیکھنہٕ آمُت چُھ۔\n25. یێلہِ تہِ چُھہ ختنہ سپدُن فٲیدٕ حٲصِل سپدان یێلہِ شریعت ہٕندِس خلاف ورزی کٔرِو، تێلہِ چُھہ ختنہ کرنہٕ آمُت۔\n26.\\tتێلہِ یێلہِ یێلہِ ختنہٕ سپدُن شریعتٕچ پاکیزگی برقرار تھاوُن، تێلہِ گژھہِ نہٕ تسُند ختنہ کرنہٕ خٲطرٕ شمار کرنہٕ؟\n27. تہٕ یُس فطری طور چھُ، یُس شریعت پورٕ کرِ، تہٕ یُس حرف تہٕ ختنہٕ سٍتـ̡ شریعت ہٕنز خلاف ورزی کران چُھ؟\n28. تکیازِ سُہ چُھ نہٕ یہودی یُس ظاہری طور اکھ چُھ۔ نہ چھہ {یہ}ختنہ یُس مازس منز نیبر کُن چھُ:\n29. مگر سُہ چُھ یہوُد، یُس باطنی چُھ۔ تہٕ ختنہ {کیا یہ} چُھہ دِلُک، روحس منز، {تہٕ} حرفس منز نہٕ؛ یٔمۍ سٕنز حمد {چھِ} نہ انسانن بلکہ خدایہ سٕندِ سٕندِس تعریفس سٍتـ̡ ۔","1. تیلہِ کیا فٲیدٕ چُھ یہودی سُند؟ یا ختنہ کرنُک کیا فٲیدٕ چُھہ؟\n2.\\tپریتھ طرفہٕ: خاص کٔرِتھ زِ تِمن سٍتـ̡ ٲس خدایہ سٕندِ نصیحت سٍتـ̡ پابند کرنہٕ آمٕژ۔\n3.\\tاگر کینہہ یقین آسہِ نہٕ کٔرتھ؟ کیا تہند کفر بنہِ خدایہ سُند ایمان بے اثر؟\n4.\\tخدا نہ کرے: آ، خدا گژھہِ پزر مگر پریتھ انسان چھہ اپُز۔ یِتھ کٔنۍ چُھ لیکھنہٕ آمُت، یُتھ زن تۅہہِ پننین کلامَن مَنٛز صٲحی گٔژھِتھ، تہٕ ییلہ تُہند فیصلہ کرنہٕ ییہِ تیلہِ ہیکہِ فتح حٲصل کٔرِتھ۔\n5. مگر اگر سانہِ ناانصافی خدایہ سٕنزِ نیکی ہٕنز تعریف کرِ، اسہِ کیا وَنُن؟ {is} خدایہ بدکار کُس چُھ انتقام نِوان؟ (بہٕ چُھس أکِس مرد سٕندِ پٲٹھۍ کتھ کران)\n6.\\tخدا نہ کرِ: تیلہِ کِتھہ پاٹھۍ کرِ خدایہ دنیاہس سٍتـ̡ فیصلہ کرنہٕ؟\n7. یێلہِ خدایہِ سُند سچُھہ میانہِ اپُزٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس جلال سٍتـ̡ زیادٕ پھٔہلِتھ آسہِ۔ وُنہِ تہِ کیازِ چُھس بہٕ گۅنہگار قرار دِنہٕ یوان؟\n8. تہٕ نہٕ {بلکہ}، (یتھ کٔنۍ أسۍ بدنام کرنہٕ آمٕتۍ چھِ، تہٕ یتھ کٔنۍ زِ أسۍ چھِ ونان ،) اسہِ کرو بد کرُن، یُتھ نیکی واتہِ؟ یٔمۍ سُند سزا چھُ منصفانہٕ۔\n9. تیلہٕ کیا چُھ؟ کیا أسۍ چھا تمن کھوتہٕ بہتر {تمن کھوتہٕ}؟ نہ، کُنہِ تہِ پٲٹھۍ: کیازِ اسہِ چُھ امہِ برونہہ یہودی تہٕ غیر یہودی ثٲبت کرمُت زِ تِم چھِ سٲری گۅنہہ گۅنہٕ سٍتـ̡ ۔ {ثٲبت: Gr. charged}\n10.\\tیتھہ پاٹھۍ لیکھنہ آمت چھہ زِ کانہہ تہِ چھہ نہ نیکس، نہ کانہہ تہِ:\n11.\\tکانہہ تہِ چُھہ نہٕ یُس خدایہ سٍتـ̡ سمجِتھ آسہِ۔\n12.\\tتِم سٲری چھِ وتہِ نِش نیران، تِم چھِ یکوٹہٕ بے نفع بٔنِتھ۔ کانہہ تہِ چھہ نہ خیر کرُن، نہ، اکھ تہِ نہ۔\n13.\\tتِہُند حلق چھُ یَلہٕ قبر۔ تِمو چُھ پننہٕ زبانہٕ سٍتۍ دھوکہ دہی استعمال کٔرمٕژ۔ یِمن ہٕندِس چپَس تَل چُھس زہر {چُھ}:\n14.\\tیمۍ سُند اوس بد دعا تہٕ تلخی سٍتۍ بٔرِتھ:\n15. تِہٕندِس کھۅر چِھہ خوُن بہاونہٕ خٲطرٕ تیز رفتار:\n16.\\tتباہی تہٕ مصیبت چھیہ پننین طریقن منز:\n17. تہٕ امن ہٕنز وتہٕ کیا چھے نہٕ تِمن پتہٕ:\n18.\\tتہنزِ نظرن برونہہ کنہِ چھہ نہ خدایہ سُند کانہہ خوف آسان۔\n19.\\tوۅنۍ چھہ اسہِ پتاہ زِ شریعت کُس تہِ کتھ چھیہ ونان تہ شریعت کِس تل چھہِ تمن تہِ ونان زِ پریتھ کُنہِ کُنہِ کتھہِ پیٹھ گژھہِ بند کرنہ یُن، تہ سورے دنیا گژھہِ خدایہ سندِ برونہہ کنہِ قصوروار بنہِ۔ {قصوروار...: یا، خدایہ سٕندِس فیصلس تابع}\n20. تێمہِ کِنۍ گژھہِ شریعت کِس اعمال سٍتـ̡ کُنہِ تہِ جسمُک جواز ثٲبت سپدُن، کیازِکہِ شریعت سٍتـ̡ چُھہ گۅناہ ہُند علم۔\n21. مگر وۅنۍ چھہ شریعت ورٲے خدایہ سنز نیکی ظٲہر سپدان، یُس شریعت تہٕ پیغمبرن ہٕندِ دٔسۍ گواہ سپدان چھُ۔\n22. یُس عیسیٰ مسیح سٕندِ ایمانہٕ سٍتـ̡ سارِنٕے تہٕ سارِنٕے ایمان تھاون والٮ۪ن خٲطرٕ چُھہ خدایہِ سٕنز نیکی تہِ: تێلہِ چُھہ نہٕ کانہہ فرق:\n23. تکیازِ سارِنٕے چُھ گۅنہہ کورمُت، تہٕ چُھہ خدایہ سٕندِ جلال نِش کم۔\n24. مسیح عیسیٰ ہس منز موجود نجات دِنہٕ سٍتـ̡ تسٕندِ فضل سٍتـ̡ آزادانہٕ پٲٹھـ̡ انصاف حٲصل سپدُن:\n25. یُس خداین پننِس خونس مَنٛز ایمان دِنہٕ سٍتـ̡ کفارہ دِژمُت چُھ، یُس خدایہ سٕندِ بردباری سٍتـ̡ پنہٕ نـ̡ گۅنہن ہٕنزِ معافی ہُند اعلان کرُن؛ {سیٹ کٔرتھ: یا، گۄڈے طے شدٕ} {معافی: یا، گزرُن}\n26.\\tیُس وِزِ تٔمِس نیکی ہُند اعلان کرُن، یُس عیسیٰ ہس پیٹھ ایمان تھاوان آسہِ، تہٕ یُس عیسیٰ ہس پیٹھ ایمان تھاوان آسہِ۔\n27.\\tتیلہِ کتہِ چھہ فخر کران؟ یہِ چھُ خٲرج کرنہٕ آمُت۔ کمہِ قونوٗن کہِ ذٔریعہٕ؟ کامہِ ہُند؟ نہ: مگر ایمان کِس قانونس مطٲبق۔\n28. تَمہِ کِنۍ چِھ أسۍ یہ نتیجہٕ اخذ کران زِ انسان چُھ شریعت کِس اعمال بغٲر ایمانہٕ سٍتـ̡ عادل قرار دِنہٕ یوان۔\n29. {کیا سُہ} چُھ صرف یہودین ہند خدا؟ {کیا سُہ تہِ چھُنہٕ غیر قومن منز؟ آ، غیر قومن ہُند تہِ:\n30. وُچھُن {یہِ} اکھ خدا، یُس ایمانہٕ سٍتـ̡ ختنہٕ کرنُک جواز پیش کرِ، تہٕ ایمانہٕ سٍتـ̡ ختنہ کرنُک جواز پیش کرِ۔\n31. کیا أسۍ چھا ایمانہٕ سٍتـ̡ شریعت کالعدم بناوان؟ خدا نخواستہ: آ، أسۍ چھہِ قانون قایم کران۔","1.\\tتیلہِ کیا ونو زِ سانہِ مٲلۍ ابراہیم چھہ مازس متعلق لوٚبمت؟\n2.\\tیێلہِ یێلہِ ابراہیمس کامہِ سٍتـ̡ انصاف سپدِ، تٔمِس چُھہ جلال حٲصل سپدان۔ مگر خدایس برونہہ کنہِ نہٕ۔\n3. صحیفہٕ کتھ خٲطرٕ چُھ ونان؟ ابراہیم اوس خدایس پیٹھ یقین تھاوان، تہٕ یہ اوس تس نیکی خٲطرٕ شمار کرنہٕ یوان۔\n4. وۅنۍ یُس کٲم کران چُھ، سُہ چُھ نہٕ فضل بلکہ قرضُک ثواب ۔\n5. مگر یُس نہٕ کٲم کران چُھ، مگر یُس بے دینی انصاف کران چُھ، تٔمۍ سُند ایمان چُھ نیکی ماننہٕ یوان۔\n6. یِتھے پٲٹھـ̡ داؤد تہِ چُھہ انسان سٕنزِ برکتُک بیان کران، یێمِس سٍتـ̡ خدا کامہِ ورٲے نیکی منسوب کران چُھ،\n7.\\t{ونان}، مبارک چھہِ تِم یِمن ہٕندِس گناہ معافی دِنہٕ آمٕتۍ تہٕ یِمن ہٕندِس گناہ چھِ پردٕ کرنہٕ آمٕتۍ۔\n8. سُہ انسان چُھ بابرکت یٔمِس پیٹھ خداوند گۅناہ عائد کرِ۔\n9.\\tیہ برکت چھا ختنہ سپدنس پیٹھ {صرف}، یا ختنہ نہ سپدنس پیٹھ تہِ؟ تکیازِ أسۍ چھہِ ونان زِ ایمانس اوس ابراہیم سٍتـ̡ نیکی خٲطرٕ شمار کرنہٕ آمُت۔\n10. تمہ پتہ کتھہ پاٹھۍ آو یہ حسابہ؟ ییلہ سُہ ختنہ اوس، یا ختنہ نہ اوس؟ ختنہ کرنس منز نہٕ بلکہ ختنہ کرنہٕ آمتس منز۔\n11.\\tتہٕ أمِس میلہِ ختنہٕ کرنٕچ نشانہٕ، یُس ایمانٕچ نیکی ہٕنز مُہر ٲس، یُس {أمِس} وُنیُک ختنہٕ اوس نہٕ آمُت کرنہٕ، یُتھ زن سُہ تِمن سارِنٕے ایمان تھاون والٮ۪ن ہُند مول بٔنِتھ، یُس نہٕ ختنہ کرنہٕ آمُت آسہِ۔ یُتھ زِ تِمن پیٹھ تہِ گژھہِ نیکی عائد کرنہٕ:\n12.\\tختنہ کرنُک مول یُس نہ صرف ختنہ کرنہٕ آمت چھُ، بلکہ یُس سٲنِس باپ ابراہیم سٕندِس عقیدس مَنٛز پکان چُھ، یُس {وُنہِ} ختنہ کرنہٕ آمُت اوس۔\n13.\\tاَتھ وعدس مۅکھہٕ زِ سُہ گژھہِ دُنیاہُک وٲرِث بنہِ، یُس نہٕ شریعت کہِ ذریعہٕ ابراہیمُک یا تٔمۍ سٕندِس اولادس سٍتـ̡ بٔلکہِ ایمانہٕ سٕندِ نیکی سٍتـ̡ بٔنِتھ۔\n14.\\tیێلہِ یێلہِ شریعت ہٕندِس وٲرِث آسن تیلہِ چُھ ایمان باطل سپدان، تہٕ وعدٕ گژھہِ نہٕ کانہہ اثر:\n15. کیازِکہ شریعت چُھ قہر کٲم کران: یتہِ نہٕ شریعت آسہِ، تتہِ چُھنہٕ کانہہ خلاف ورزی سپدان۔\n16.\\tتێلہِ {یہِ} چُھہ ایمانُک، یُس {یہِ فضل سٍتـ̡ سپدِ}؛ ٲخرس تام ہیکہِ وعدہ سارِنٕے بیٲلِس پیٹھ یقینی ٲسِتھ۔ نہ صرف تتھ کُن یُس شریعت سٍتـ̡ چُھ، بلکہ تتھ سٍتـ̡ یُس ابراہیم سٕندِس عقیدس سٍتـ̡ چُھ۔ یُس اسہِ سارِنٕے ہُند مول چُھ،\n17. (یُتھ زن یہ لیکھنہٕ آمُت چُھ، مے چُھہ ژے واریاہن قومن ہُند مول بنوومُت،) تٔمِس برونہہ کُن یُس سُہ ایمان اوس تھاوان، {حتیٰ کہ} خدایہ، یُس مُردن زندٕ کران چُھ، تہٕ تِمن چیزن بلاوان چُھ یِم نہٕ تِمن ہٕندِس پٲٹھۍ۔ {امس برونہہ: یا، امس پٲٹھۍ}\n18.\\tیُس وۅمید کِس خلاف وۅمید پٲٹھـ̡ پژھ تھاوان چُھ، یێلہِ سُہ بنہِ واریہن قومن ہُند مول، یُس وننہٕ آمُت چُھ، تۯێلہِ گژھہِ تُہند اولاد۔\n19.\\tتہٕ ایمان منز کمزور آسنہ کِنۍ، سُہ اوس نہٕ پنُن جسمہٕ وُنۍ موٗدمُت، ییلہ سُہ ہتھ ؤری وٲنسہِ اوس، تہٕ نہ اوس سارہ سٕندِ رحمُک مرُن۔\n20.\\tسُہ اوس نہٕ کُفر سٍتـ̡ خدایہ سٕندِس وعدس سٍتـ̡ لڑکھان۔ مگر اوس ایمانس منز مضبوط، خدایہ سُند جلال دِوان۔\n21.\\tتہٕ پوٗرٕ پٲٹھـ̡ یقین سپدِتھ زِ یُس وعدٕ اوس کورمُت، سُہ اوس انجام دِنس قٲبل۔\n22.\\tتہٕ امہِ مۅکھہ آو یہ أمِس نیکی ہٕندِ خٲطرٕ مُقرر کرنہٕ۔\n23.\\tوۅنۍ اوس نہ یہ صرف تمۍ سندِ خاطرہ لیکھنہ آمت، یہ اوس تس پیٹھ لگاونہ آمت۔\n24. مگر اسہِ خٲطرٕ تہِ، یٔمِس سٍتـ̡ یہ ذمہ دار آسہِ، یێلہِ أسـ̡ تٔمِس پى۪ٹھـ̡ یُس عیسیٰ مسیح مُردٕ پى۪ٹھہٕ زندٕ کٔرِتھ چُھہ یێلہِ أسـ̡ پى۪ٹھـ̡ پى۪ٹھ۔\n25. یُس سانہِ جُرمَن خٲطرٕ دِنہٕ آو، تہٕ سُہ آو سانہِ جوازٕ خٲطرٕ دُبارٕ وُتھنہٕ۔","1. تێمہِ کِنۍ چُھہ ایمانہٕ سٍتـ̡ راستباز سپدِتھ أسـ̡ پننِس خداوند عیسیٰ مسیحس سٍتـ̡ خدایہِ سٍتـ̡ امن حٲصل سپدان۔\n2. ییمہِ سٍتـ̡ أسـ̡ ایمانہٕ سٍتـ̡ اتھ فضل سٍتـ̡ رسٲیی حٲصل سپدان چِھ، یێمہِ سٍتـ̡ أسـ̡ خدایہِ سٕندِ جلال سٍتـ̡ وۅمید کران چھِ۔\n3. تہٕ نہ صرف {توتہِ}، بلکہ چھِ أسۍ مصیبتَن مَنٛز تہِ فخر کران: یہ زٲنِتھ زِ مصیبت چھِ صبر کٲم کران۔\n4. تہٕ صبر، تجربہٕ؛ تہٕ تجربہٕ، امید:\n5. تہٕ وۅمید چھے نہٕ شرم کران۔ تکیازِ خدایہ سُند محبت چُھ سانین دلن مَنٛز روح القدس سٍتـ̡ یُس اسہِ دِنہٕ آمُت چُھ۔\n6. یێلہِ أسـ̡ بێیہِ طاقتس سٍتـ̡ أسـ̡ مُقرر وقتس سٍتـ̡ مسیح مرُن کافرن ہٕندِ خٲطرٕ۔ {مُقرر وقتس منز: یا، وقتس مطٲبق}\n7.\\tیِکیازِ أکِس نیک انسانس سٍتـ̡ چُھہ نہٕ کانہہ مرُن، توتہِ چھُ أکِس نیک انسانس سٍتـ̡ مرنٕچ ہمت تہِ کٔرِتھ۔\n8. مگر خدا چُھ اسہِ سٍتـ̡ پَنٕنـ̡ محبتٕچ تعریف کران، یێلہِ أسـ̡ أسـ̡ گۅنہگار ٲسِو، مسیح موٗد سانہِ خٲطرٕ۔\n9.\\tامہِ پٲٹھـ̡ یێلہِ چُھہ تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ بێیہِ سٍتـ̡ نجات دِنہٕ۔\n10. یێلہِ أسـ̡ دُشمن أسـ̡ أسـ̡ خدایہِ سٕندِ نیچوِ سٕندِ مرنہٕ سٍتـ̡ صلح کرنہٕ سٍتـ̡ أسـ̡ تسٕندِ زُو سٍتـ̡ نجات دِنہٕ۔\n11. تہٕ نہ صرف {توتہِ}، بلکہ چِھ أسـ̡ پننِس آغہٕ عیسیٰ مسیح سٕندِ سٍتـ̡ خدایہِ سٕندِ سٍتـ̡ خوشی حٲصل کٔرِتھ، یٔمِس سٍتـ̡ أسـ̡ وۅنۍ کفارہ حٲصل سپدمُت چُھ۔ {کفارہ: یا، مصالحت}\n12. تێلہِ گۆو أکِس انسانس سٍتـ̡ گۅناہ دنیاہس مَنٛز دٲخل تہٕ گۅنہٕ سٍتـ̡ موت۔ تہٕ یِتھٕ پٲٹھۍ گوٚو موت سارنٕے انسانن پیٹھ، تکیازِ سارِنٕے چھُ گۅنہہ کورمُت: {تَمہِ خٲطرٕ: یا، کٔمِس منز}\n13. (تکیازِ یوتام شریعت گۅناہ دنیاہس مَنٛز اوس، مگر گۅناہ چُھنہٕ تیلہِ چُھنہٕ شریعت آسنہٕ وِزِ گۅناہ لاگنہٕ یِوان۔\n14. بہر حال اوس آدم سٕندِ سٍتـ̡ موسیٰ سٕندِس سٍتـ̡ موسیٰ سٕندِس سٍتـ̡ موسیٰ سٕندِس سٍتـ̡ موتـ̡ بادشاہ گومُت، یُس نہٕ آدم سٕندِ خطا سٍتـ̡ گۅناہ کورمُت اوس، یُس یُس یِنہٕ وول اوس۔\n15.\\tمگر جرم کِس طورس پیٹھ نہٕ، تِتھے پٲٹھۍ چھُ مُفت تحفہٕ تہِ۔ یێلہِ أکِس سٕندِ جُرمَس سٍتـ̡ واریاہ سٕندِ جُرمَس سٍتـ̡ چُھہ خدایہِ سُند فضل تہٕ فضل سٍتـ̡ یُس أکِس شخصہٕ عیسیٰ مسیح سٕندِ دٔسۍ دِنہٕ آمُت چُھ، واریاہن ہٕندِس خٲطرٕ چُھ واریاہ زیادٕ سپدان۔\n16.\\tتہٕ یُتھ زن {یہ} گۅنہگار کٔرِتھ {یہ} گۅنہگار کٔرِتھ، {تِتھے پٲٹھۍ} تحفہٕ: یێلہِ کُنہِ سٍتـ̡ سزا دِنہٕ آمُت، مگر مُفت تحفہٕ {چُھ} واریاہن جُرمَن ہُند جواز دِنہٕ خٲطرٕ۔\n17.\\tیێلہِ أکِس شخصہٕ سٕندِ جُرمَس سٍتـ̡ سٍتـ̡ موت سپدِ۔ واریاہ زیادٕ یِم فضل تہٕ نیکی ہٕندِ تحفہٕ حٲصل سپدان چِھہ زندگی مَنٛز حضرت عیسیٰ مسیح سٕندِ دٔسۍ حکومت کرنہٕ۔) {أکِس شخٕص سٕندِس ذریعہٕ...: یا، أکِس جُرمَس سٍتۍ}\n18.\\tتێلہِ یێلہِ اَکہِ {فیصلہٕ} کِس جُرمس سٍتـ̡ سارنٕے انسانن پیٹھ مذمت کرنہٕ خٲطرٕ۔ توتہِ چُھ أکِس سٕنزِ نیکی سٍتـ̡ سارنٕے انسانن ہٕندِ خٲطرٕ زندگی ہٕندِس جوازس مُتلق دِنہٕ آمُت۔ {جرم کہِ ذریعہ...: یا، اکہِ جُرم} {نیکی سٍتـ̡...: یا، أکِس نیکی سٍتـ̡\n19.\\tیِتھٕ پٲٹھـ̡ أکِس انسانہٕ سٕنزِ نافرمانی سٍتـ̡ واریاہ گۅنہگار بٔنِتھ گۅنہگار بٔنِتھ گٔیہِ۔\n20.\\tامہ علاوہ آو قانون دراو زِ جرم گژھہِ واریاہ زیادہ۔ مگر ییتہِ گۅناہ واریاہ زیادٕ اوس، فضل کٔر واریاہ زیادٕ:\n21. یِتھٕ پٲٹھـ̡ گۅناہ چُھہ موتس تام بادشاہ سپدمُت، تۂ یێلہِ پى۪ٹھہٕ گژھہِ عیسیٰ مسیح سٕندِ سٍتـ̡ ابدی زندگی ہٕندِس سٍتـ̡ فضل کٔرِتھ۔","1. تیلہِ کیا ونو اسہِ؟ کیا أسۍ پٲٹھـ̡ گۅنہٕ سٍتـ̡ جٲری تھاوُن، یُتھ فضل گژھہِ بٔرِتھ؟\n2. خدا نہ کرے۔ أسۍ، یُس گۅنہٕ سٍتـ̡ موٗدمُت چُھ، کِتھہٕ کٔنۍ روزو اَتھ مَنٛز زندٕ؟\n3. کیا تۅہہِ چھے نہٕ پتاہ زِ اسہِ مَنٛز واریاہ یِم عیسیٰ مسیحس مَنٛز بپتسمہ دِنہٕ آمٕتۍ ٲسۍ، تٔمۍ سٕندِس مرنس مَنٛز آیہ بپتسمہ دِنہٕ؟ {وَر: یا، چھِ}\n4. تێمہِ کِنۍ چُھہ أسـ̡ أمِس سٍتـ̡ بپتسمہ دِنہٕ سٍتـ̡ موتس مَنٛز دفن کرنہٕ آمُت: یِتھٕ پٲٹھـ̡ عیسیٰ مسیح باپ سٕندِ جلال سٍتـ̡ مُردٕ سٍتـ̡ زندٕ گومُت، تِتھے پٲٹھـ̡ پزِ أسـ̡ زندگی ہٕندِس نوِ پٲٹھـ̡ پَکُن۔\n5. یێلہِ أسـ̡ تٔمۍ سٕندِس مرنہٕ سٍتـ̡ یکوٹہٕ لاگنہٕ آمٕتـ̡ أسـ̡ أسـ̡ {تسٕندِس} قیامتٕچ مثالہٕ سٍتـ̡ بٔنِتھ:\n6. یہ زانِتھ زِ سٲنـ̡ بُزرگ چُھہ سٍتـ̡ صلیب دِنہٕ آمُت، یُتھ گۅنہٕ سُند جسم گژھہِ تباہ کرنہٕ، یێلہِ پَزِ نہٕ أسـ̡ گۅنہٕ سٍتـ̡ خدمت کرنہٕ۔\n7.\\tیُس مرُن چُھہ سُہ چُھ گۅنہٕ نِش آزاد سپدان۔ {آزاد: Gr. justified}\n8. یێلہِ أسـ̡ مسیحس سٍتـ̡ مٔرِتھ أسـ̡ أسـ̡ پى۪ٹھہٕ پى۪ٹھ۔\n9. یہ زانِتھ زِ مسیح چُھ نہٕ مُردٕ منزٕ زندٕ سپدُن مَرُن۔ تس پیٹھ چھہ نہ موتس کانہہ غلبہ۔\n10. یێمہِ سٍتـ̡ سُہ مرُن، سُہ چُھ اکہِ لٹہِ گۅنہٕ سٍتـ̡ مرُن، مگر یێمہِ سٍتـ̡ سُہ زندٕ روزان چُھ، سُہ چُھ خدایہ سٕندِ خٲطرٕ زندٕ روزان۔\n11. یِتھے پٲٹھـ̡ چُھہ تُہۍ تہِ گۅنہٕ سٍتـ̡ موٗدمُت، بلکہ چُھہ عیسیٰ مسیح سٕندِ سٍتـ̡ خدایہِ سٕندِ سٍتـ̡ زندٕ۔\n12. تێمہِ کِنۍ گژھہِ نہٕ گۅناہ پننِس فانی جسمس مَنٛز راج کرُن، یُتھ زِ تۅہہ گژھہِ تٔمِس ہوس مَنٛز اطاعت کٔرِتھ۔\n13. پَنٕنـ̡ بێیہِ ہٕندِس آلہٕ سٍتـ̡ بێیہِ گۅنہٕ سٍتـ̡ دِیُو، بٔلکہِ پَنُن پان خدایہِ سٍتـ̡ پیش کٔرِو، یِتھٕ پٲٹھـ̡ یِم مُردٕ پى۪ٹھٕ زندٕ چِھہ، تہٕ پَنٕنـ̡ رُکُن خدایہِ سٕندِس سٍتـ̡ پاکیزگی ہٕندِس آلہٕ سٍتـ̡ ۔ {آلات: Gr. arms, or, weapons}\n14. تکیازِ گۅناہ گژھہِ نہٕ توے سٍتـ̡ تُہٕندِس سٍتـ̡ حاکمیت حٲصِل کٔرِتھ، تکیازِ تُہۍ چِھہ نہٕ شریعتس تحت بلکہ فضل سٍتـ̡ ۔\n15. تیلہٕ کیا چُھ؟ کیا أسۍ گۅنہہ کٔرِتھ، کیازِ أسۍ چھِنہٕ قانونس تحت بلکہ فضل کِس تحت؟ خدا نہ کرِ۔\n16.\\tتہِ چھُنہٕ پتاہ زِ یێمہِ سٕندِس خادمَس اطاعت کرنہٕ خٲطرٕ تہٕ تٔمۍ سٕندِس خادمَس سٍتـ̡ چھِو تٔمۍ سٕندِس خادمَس سٍتـ̡ یِمن ہٕنز اطاعت کران چھِو۔ مرنس تام گۅناہ یا نیکی ہٕنز فرمانبرداری؟\n17.\\tمگر خدایہ سُند شُکر گُزٲر زِ تہۍ ٲسِو گۅنہٕ ہٕندِ خادم، مگر تۅہہ کٔر دِلہٕ سٍتـ̡ تمہِ نظریہٕچ فرمانبرداری یُس ژے دِل دِنہٕ آمُت اوس۔ {کُم...: Gr. کتہِ تم آیہ ڈیلیورڈ}\n18.\\tگۅنہٕ نِش آزاد سپدِتھ بنیوو تم نیکی ہٕندِس خادم۔\n19. بہٕ چُھس پننہِ مازٕچ کمزوری کِنۍ انسانن ہٕندِس طریقس مطٲبق کتھ کران: یِتھ کٔنۍ ژے پَنٕنٕنـ̡ پَنٕنـ̡ خادمَن ناپاک تہٕ بدکاری ہٕندِس سٍتـ̡ دِژمٕژ چھِ۔ توتہِ کٔرِو وۅنۍ پَنٕنـ̡ رُکُنـ̡ پاکیزگی ہٕندِس خادمَس سٍتـ̡ دِنہٕ۔\n20. ییلہ تم گۅنہہ ہٕندِ خادم ٲسو، تہٕ ٲسِو نیکی نِش آزاد۔ {منز...: Gr. تا نیکی}\n21.\\tتِمن چیزن مَنٛز کُس پھل اوسُکھ یِمن سٍتـ̡ وۅنۍ شرمندہ چُھہ؟ تِمن چیزن ہُند اند {چُھ} موت۔\n22. مگر وۄنۍ گۅنہٕ نِش آزاد سپدِتھ تہٕ خدایہِ سٕندِ خادم بٔنِتھ، تہٕ چُھہ تُہُند پھل پاکیزگی تہٕ ٲخری ابدی زندگی حٲصِل سپدان۔\n23. گۅنہٕ سٕندِ اجرت خٲطرٕ {چُھ} موت؛ مگر خدایہِ سُند تحفہٕ چُھہ عیسیٰ مسیح سٕندِ ذریعہٕ ابدی زندگی۔","1. تۅہہ چھے نہٕ پتاہ زِ بہٕ چُھس شریعت زانان تِمن سٍتـ̡ کِتھہ پٲٹھـ̡ چُھہ شریعت سٍتـ̡ یێلہِ سُہ زندٕ روزان چُھہ؟\n2. یۅسہٕ زنانہِ خاوند آسہِ، سُہ چُھہ یوتام زندٕ روزِ، سُہ چُھ شریعہٕ سٍتـ̡ پابند آسان۔ مگر اگر خاوند مرُن آسہِ، سۅ چھیہ {پننِس} خاوندس نشہِ آزاد سپدان۔\n3. تیلہِ یێلہِ یێلہِ تٔمِس خاوند زندٕ آسہِ، تیلہِ گژھہِ تس زناکار وننہٕ یُن، مگر اگر تٔمۍ سُند خاوند مرُن آسہِ، سۅ گژھہِ تمہِ قانونہٕ نِش آزاد۔ تاکہ سۄ آسہٕ نہٕ زانکٲری کٔرتھ، حالانکہ أمس گژھہٕ بییس مردس سۭتۍ خانٛدر کرنہٕ۔\n4. تێمہِ مۅکھہٕ چُھہ میٲنۍ بٲے تہِ عیسیٰ سٕندِ جسمہٕ سٍتـ̡ شریعت سٍتـ̡ موٗدمُت۔ یُتھ زِ تۅہہ گژھہِ بییِس سٍتـ̡ خاندر کرنہٕ یُن، یُس مُردٕ منزٕ زندٕ سپدِ، یُتھ أسـ̡ خدایہِ سٍتـ̡ پھل دِنہٕ یُن۔\n5. یێلہِ أسـ̡ جسمس مَنٛز أسـ̡ ، گۅنہٕ ہٕنزِ حرکتہٕ، یُس شریعت کہِ مطٲبق اوس، سانین ارکانن مَنٛز پھل دِنہٕ خٲطرٕ کٲم کٔرِ۔ {حرکتہٕ: Gr. passions}\n6. مگر وۅنۍ چھہِ اسہِ شریعت نِش نجات دِنہٕ آمٕژ، یُس مٔرِتھ أسۍ رٔٹِتھ ٲسۍ۔ زِ اسہِ پزِ روح کس نوس منز خدمت کرٕنۍ، نہ کہ حرفچ پرانہِ آسنس منز۔ {یہِ چھُ...: یا، تَمہِ خٲطرٕ موٗدمُت}\n7. تیلہِ کیا ونو اسہِ؟ {کیا} قانون چھہ گناہ؟ خدا نہ کرِ۔ نہ، میہ اوس نہ گۅناہ زانان، بلکہ شریعت سٍتۍ، کیازِ میہ اوس نہ ہوس زانان، مگر شریعت اوس ووٚنمُت، ژے گژھ نہٕ لالچ کٔرتھ۔ {ہوس: یا، کنکوپسنس}\n8.\\tمگر گۅناہ کٔر حُکمہٕ سٍتـ̡ موقعہٕ رٔٹِتھ میانہِ مَنٛز پرٮ۪تھ قٕسمٕچ عیاشی پٲدٕ۔ تکیازِ شریعت ورٲے اوس گۅناہ {اوس} موٗدمُت۔\n9. کیازِ بہٕ اوسُس اکہِ لٹہِ شریعت ورٲے زندٕ، مگر ییلہ حکم آو تہٕ گۅناہ گۆو زندٕ، تہٕ بہٕ موٗد۔\n10. تہٕ سُہ حُکم، یُس {زِندٕ خٲطرٕ مقرر کرنہٕ آمُت}، مے وُچھ {سُہ} مرنس تام۔\n11.\\tگۅنہہ کِنۍ کٔرِتھ کٔرِن میہ دوکھہٕ دِتھ تہٕ اَمہ سٍتـ̡ مارُن {مے}۔\n12. اَمہِ مۄکھٕ چُھ شریعت {پاک}، تہٕ حکم چُھ مُقدس، تہٕ منصف، تہٕ اصل۔\n13.\\tتیلہِ اوسا یُس نیک چھہ میانہِ خاطرہ مرُن؟ خدا نہ کرِ۔ مگر گناہ، یُس گۅناہ ظٲہر گژھہِ، یُس میہ منز نیک چُھہ سٍتـ̡ موتُک کٲم کٔرِتھ۔ یُس حکمہٕ سٍتـ̡ گۅناہ سپدِتھ ہیکہِ زیادٕ گۅناہ بٔنِتھ۔\n14. کیازِ أسۍ چھِ زانان زِ شریعت چُھہ روحانی: مگر بہٕ چُھس جسمانی، یُس گۅنہٕ سٍتـ̡ کٕننہٕ آمُت چُھ۔\n15. یُس بہٕ کران چُھس بہٕ چُھس نہٕ اجازت دِوان: یُس بہٕ کرُن، سُہ چُھس نہٕ کرُن؛ مگر میہ یُس نفرت چھُ، سہ چھہ میہ کران۔ {اجازت: Gr. know}\n16. اگر بہٕ سُہ کٔرِتھ یُس نہٕ بہٕ کرِ، بہٕ چُھس اتھ قانونس سٍتۍ رضامندی دِوان زِ یہِ چُھہ اصل۔\n17. وۅنۍ چُھہ نہٕ بہٕ یہِ کران بلکہ چُھہ گۅناہ یُس میٲنس مَنٛز روزان چُھ۔\n18.\\tکیازِ بہٕ چُھس پتاہ زِ میٲنس مَنٛز چُھہ نہٕ کانہہ اصل چیز روزان، تکیازِ مرضی چُھہ میہ سٍتـ̡ موجود۔ مگر {کتھہ پاٹھۍ} کرُن یُس اصل چھہ میہ باسان چھُ۔\n19. یُس بہٕ کرٕ نہٕ بہٕ کرُن، مگر سُہ بُرٕ یُس بہٕ کرٕ نہٕ، یُس بہٕ کرُن۔\n20. وۅنۍ اگر بہٕ یہ کرِ، بہٕ کرٕ نہٕ بہٕ یہِ کرُن، بلکہ چھُس گۅناہ یُس میٲنس مَنٛز روزان چُھ۔\n21.\\tمیہ چھہ اَمہ پتہٕ اکھ قانون میلان زِ ییلہ بہٕ نیکی کرِ، بد کار چھہ میہ سٍتۍ موجود۔\n22. کیازِ بہٕ چُھس باطنی انسانس پتہٕ خدایہ سٕندِس قانونس سٍتـ̡ خوش گژھان:\n23. مگر بہٕ چُھس پننین ارکانن منز بیاکھ قانون وچھان، یُس میٲنس ذہنس کِس قانونس خلاف جنگ کران چُھ، تہٕ میہ چُھ گۅنہٕ کِس قانونس منز قید کران یُس میانین ارکانن منز چُھ۔\n24. اے بدبخت انسان یُس بہٕ چھُس! کُس کرِ میہ امہِ موتٕچ لاشہٕ نِش بچاو؟ {جسم...: یا، یہ موتُک جسم}\n25. بہٕ چُھس عیسیٰ مسیح سٕندِ ذریعہٕ خدایہِ سُند شُکر ادا کران۔ تێلہِ چُھس ذہنس سٍتـ̡ بہٕ پانہٕ خدایہِ سٕندِ قانونٕچ خدمت کران۔ مگر مازس سٍتـ̡ گۅنہٕ سُند قانون۔","1. {لہذا} چُھہ نہٕ تِمن سٍتـ̡ کانہہ مذمت یُس مسیح عیسیٰ ہس مَنٛز چُھ، یُس نہٕ جسمہٕ پَتہٕ پکان چُھ، بٔلکہِ روٝحہٕ سٕندِس پَتہٕ پَکان چُھ۔\n2. عیسیٰ مسیحس مَنٛز روح زندگی ہٕندِ شریعت سٍتـ̡ چُھہ میہ گۅنہٕ تہٕ موتٕکہِ شریعت نِش آزاد کورمُت۔\n3. یُس شریعت ہیوٚک نہٕ کٔرِتھ، یێمہِ سٍتـ̡ سُہ مازٕ سٍتـ̡ کمزور اوس، خداین سوزُن پَنُن نیچو گۅنہٕ مازٕ سٕندِس مشافس سٍتـ̡ تہٕ گۅنہٕ سٍتـ̡ گۅنہٕ سٍتـ̡ مذمت کٔرِتھ: {گۅنہٕ خٲطرٕ: یا گۅنہٕ سٍتـ̡ قربانی دِنہٕ سٍتـ̡\n4. یُتھ زِ شریعت ہٕنز پاکیزگی گژھہِ اسہِ مَنٛز پورٕ، یُس نہٕ جسمہٕ پَتہٕ پکان چُھ، بٔلکہِ روٝحہٕ سٕندِ پَتہٕ پَکُن۔\n5. یِم ماز پَتہٕ چھِ تِم چھِ مازٕچ چیزن ہُند خیال تھاوان۔ مگر تِم یِم روحہٕ سٕندِ پَتہٕ چِھہ روح سٕندِ چیز۔\n6.\\tجسمانی ذہنیت تھاون سٍتـ̡ موت؛ مگر روحٲنی طور ذہنیت تھاوُن چھُ زندگی تہٕ سکون۔ {جسمٲنی آسُن...: Gr. مازُک ذہن} {روحٲنی طور آسُن...: Gr. روح سُند ذہن}\n7. کیازِکہ جسمٲنی ذہن چُھ خدایہ سٕندِس خلاف دشمنی: کیازِ یہٕ چُھنہٕ خدایہ سٕندِس قانونس تابع تہٕ نہ ہیکہِ ٲسِتھ۔ {جسم...: Gr. مازُک ذہن}\n8.\\tتێلہِ یێلہِ یِم جسمس مَنٛز چھِ تِم ہیکن نہٕ خدایہ خوش کٔرِتھ۔\n9. مگر تُہۍ چھِو نہٕ جسمس مَنٛز، بٔلکہِ روحس مَنٛز، یێلہِ تہِ چُھہ خدایہِ سُند روح توے مَنٛز روزُن۔ وۅنۍ یێلہِ کٲنسہِ انسانس مسیح سُند روح چُھ، سُہ چُھہ نہٕ أمِس سٍتـ̡ کانہہ تہِ۔\n10. تہٕ یێلہِ مسیح چُھہ تۅہہِ مَنٛز {be}، جسم چُھہ گۅنہٕ سٍتـ̡ موٗدمُت۔ مگر روح چُھ نیکی سٍتـ̡ زندگی دِوان۔\n11. یێلہِ عیسیٰ مسیح مُردٕ منزٕ زندٕ کٔرِتھ چُھہ، سُہ تہِ کرِ تُہٕندِس فانی جسمس زندٕ یُس تۅہہِ مَنٛز روزان چُھ۔ {by: یا، کیازِ}\n12. تێمہِ کِنۍ، بٲے ، أسـ̡ چِھہ مازس سٍتـ̡ قروض ، یێلہِ چُھہ ماز پَتہٕ زندٕ روزنہٕ خٲطرٕ۔\n13.\\tیێلہِ یێلہِ تہٕ\n14. یێلہِ خدایہِ سٕندِ روٝحہِ سٍتـ̡ چِھہ تِم خدایہِ سٕندِ فرزند۔\n15.\\tکیازِ ژے چُھہ نہٕ دُبارٕ غلامی ہُند روح حٲصل سپدمُت۔ مگر ژے چُھہ رٹنہٕ ہُند روح حٲصل گومُت، ییمہ سٍتـ̡ أسـ̡ روٝحہِ ہُند روٝحہٕ چُھ، اَبا، بابا۔\n16. روح چُھ پانہٕ سانہِ روحہٕ سٍتـ̡ گوٲہی دِوان زِ أسـ̡ چِھہ خدایہِ سٕندِ شُرۍ:\n17. تہٕ اگر بچہٕ، تیلہٕ وٲرث۔ خدایہِ سٕندِ وٲرِث، تہٕ مسیحس سٍتـ̡ مُشترکہٕ وٲرِث۔ یێلہِ أسـ̡ أسـ̡ سٍتـ̡ مُتٲثِر سپدِو، یێلہِ أسـ̡ أسـ̡ رٔلِتھ تہِ گٔژھِتھ گٔژھِو۔\n18.\\tتکیازِ بہٕ چُھس باسان زِ یَتھ وقتٕچ مصیبت چھِنہٕ تتھ عظمتس سٍتۍ موازنہٕ کرنہٕ یُس اسہِ مَنٛز ظٲہر سپدِ۔\n19.\\tمخلوق سٕنزِ سٍتـ̡ وۅمید چُھہ خدایہ سٕندِس فرزندن ہٕندِس ظہورُک انتظار۔\n20.\\tتکیازِ مخلوق ٲس نہ پننہِ مرضی سٍتـ̡ بےکار بناونہٕ آمٕژ، بلکہ ییمہِ سٍتـ̡ وۅمید سٍتـ̡ {یێمہِ} تابع آسہِ،\n21. تکیازِ مخلوق تہِ گژھہِ بد عنوانی ہٕنزِ غلامی نشہِ خدایہ سٕندِ اولاد سٕنزِ شاندار آزٲدی منز نجات دِنہٕ۔\n22.\\tتکیازِ اسہِ چھیہ پتاہ زِ سورے مخلوق چھیہ از تام رٔلتھ دگ کران تہ دگ کران۔ {the...: یا، پرتھ مخلوق}\n23. تہٕ نہ صرف {تِم}، بلکہ پانس تہِ، یُس روحُک گۄڈنِک پھل چُھ، حتیٰ کہ أسۍ تہِ چھِ پانس اندر نِش گڑبڑ کران، پننِس جسمٕچ نجات دِنُک انتظار۔\n24.\\tکیازِ أسۍ چھہِ وۅمید سٍتـ̡ نجات دِنہٕ آمٕژ، مگر وۅمید یُس وُچھان چُھ، سُہ کیازِ چُھ وۅمید تھاوان؟\n25.\\tمگر اگر اسۍ یہ وۅمید کران چھہِ زِ اسۍ چھہِ نہ وچھان، {تیلہِ} چھہِ اسۍ صبر سان انتظار۔\n26. یِتھے پٲٹھـ̡ چُھ روح تہِ سانہِ کمزورین منز مدد کران: تکیازِ أسـ̡ چُھہ نہٕ پتاہ زِ اسہِ کیاہ خٲطرٕ پزِ دُعا کرُن، مگر روح چُھ پانہٕ سانہِ خٲطرٕ شفاعت کران یُس نہٕ کٔرِتھ ہیکو نہٕ۔\n27.\\tیُس دِل ژھانڈان چُھہ سُہ چُھ زانان زِ روح سُند ذہن کیا چُھ، کیازِ سُہ چُھ خدایہ سٕنزِ مرضی مطٲبق مقدسن ہٕندِ خٲطرٕ شفاعت کران۔ {کیازِ: یا، یہ}\n28. تہٕ أسۍ چھِ زانان زِ سٲری چیز چھِ تِمن ہٕندِ خٲطرٕ رٔلِتھ کٲم کران یِم خدایہ سٕندِ مَقصَدس مُطٲبِق بُلاونہٕ آمٕتۍ چھِ۔\n29.\\tیٔمِس سٍتـ̡ أمِس پیشگی زانان اوس، تٔمِس تہِ اوس پننِس نیچوِس سٕنزِ شکلہِ مُطٲبق مُقرر کورمُت، یُتھ سُہ آسہِ واریاہن باین مَنٛز گۄڈنیُک زامُت۔\n30.\\tیِمن سٍتـ̡ یێمہِ سٍتـ̡ یێلہِ سٍتـ̡ تِمن تہِ بُلاونہٕ آمُت، تہٕ یێمِس سٍتـ̡ أمِس بُلاونہٕ آمُت اوس، تِمن تہِ اوس تِمن ہٕندِس جلال س\n31.\\tتیلہِ کیا ونو اسہِ یمن چیزن پیٹھ؟ اگر خدا اسہِ خٲطرٕ آسہِ، اسہِ خلاف کُس ہیکہِ ٲسِتھ؟\n32.\\tیُس نہٕ پنُن نیچو بچٲوِتھ بلکہ اسہِ سارِنٕے خٲطرٕ دِیُت، سُہ کِتھہ کٔنۍ دِیہِ نہٕ أمِس سٍتـ̡ سٲری چیز دِنہٕ؟\n33. کُس کرِ خدایہ سٕندِس منتخب سٕندِس ذمہ دارس سٍتـ̡ کانہہ چیز؟ {یہٕ چُھ} خدا یُس جواز پیش کران چُھ۔\n34. سُہ کُس چُھ یُس مذمت کران چُھ؟ {یہٕ چُھ} مسیح یُس مرُن، ہاں بٔلکہِ، سُہ چُھ دُبارٕ زندٕ سپدان، یُس خدایہ سٕندِس دچھنہٕ اتھس پیٹھ تہِ چُھ، یُس اسہِ خٲطرٕ شفاعت تہِ کران چُھ۔\n35. کُس کرِ اسہِ مسیح سٕندِ محبتہٕ نِش الگ کرنہٕ؟ مصیبت، یا مصیبت، یا ظلم، یا قحط، یا ننگہ، یا خطرہ، یا تلوار؟\n36. یِتھ کٔنۍ چُھ لیکھنہٕ آمُت، تہندِ خٲطرٕ چِھ أسۍ سٲرۍسٕے دۅہس مارنہٕ یوان۔ أسۍ چھِ ذبح کرنہٕ خٲطرٕ کۅکرِ ہٕندۍ پٲٹھۍ شمار کرنہٕ آمٕتۍ۔\n37. نہ، یِمن سارِنٕے چیزن منز چھِ أسۍ تسٕندِ سٍتـ̡ فاتح سٍتـ̡ زیادٕ زیادٕ یُس اسہِ محبت کران چُھ۔\n38.\\tکیازِ بہٕ چُھس یقین زِ نہ موت، نہ زندگی، نہ فرشتہٕ، نہ سلطنت، نہ طاقت، نہ موجودٕ چیز، تہٕ یِنہٕ وٲلِس چیز،\n39. نہ تھزر، نہ گہرایی تہٕ نہ بییہ کانہہ مخلوق ہێکہِ اسہِ خدایہ سٕندِ محبتہٕ نِش الگ کٔرِتھ، یُس مسیح عیسیٰ مسیح سٕندِس آغس منز چُھ۔","1. بہٕ چُھس مسیحس مَنٛز حقیٖقت ونان ، بہٕ چُھس نہٕ اپُز، میون ضمیر تہِ چُھہ روح القدس سٕنز گواہی دِوان،\n2. زِ میٲنِس دِلس منز چُھ سٮ۪ٹھاہ گۄب تہٕ مُسلسل غم۔\n3. تکیازِ بہٕ ہیوٚک یژھان زِ پانس گژھہِ مسیح سٕندِ طرفہٕ پننین باین ہٕندِ خٲطرٕ، میانین رشتہٕ دارن ہٕندِ خٲطرٕ یِم ماز مطٲبق ملعون کرنہٕ آمٕتۍ: {لعنت: یا، الگ کرنہٕ}\n4. بنی اسرائیل کُس چُھ؟ یٔمِس سٍتـ̡ {متعلق} چُھہ گود نِن، تہٕ عظمت، تہٕ عہد تہٕ شریعت دِنُک، تہٕ خدایہِ سٕنزِ خدمت، تہٕ وعدٕ سٍتـ̡ ۔ {معاہدٕ: یا، وصیت}\n5. یێمہِ سٕندِس باپَس سٍتـ̡ چُھہ یێمہِ سٍتـ̡ مسیح {آو}، یُس سارِنٕے سٍتـ̡ چُھہ، یُس سارِنٕے سٍتـ̡ چُھ، خدا چُھہ ہمیشہٕ خٲطرٕ آمین۔\n6. یێلہِ چُھہ نہٕ خدایہِ سٕندِ کلامُک کانہہ اثر پیوٚومُت۔ تِکیازِ تِم چھِنہٕ سارِنٕے اِسرٲیل، یُس اسرٲیلِس سٍتـ̡ چُھ:\n7. تہٕ نہٕ، تِکیازِ تِم چھِ ابراہیم سٕنز اولاد، {کیا تِم چھِ} سارِنٕے شُرۍ: مگر اسحاق سٕندِس سٍتـ̡ یِیہِ تُہٕندِس بُلِس بُلاونہٕ۔\n8. یعنی، یِم ماز سٕندِ اولاد چِھہ، یِم چِھنہٕ خدایہِ سٕندِ اولاد چِھہ، مگر وعدٕکہٕ سٕندِ اولاد چِھ بُلکہٕ سٕندِ خٲطرٕ شمار کرنہٕ یوان۔\n9.\\tامہ مۅکھہ چھہ وعدک لفظ، یمہِ وِزِ بہٕ یِنہٕ تہٕ سارہ گژھہِ اکھ نیچو۔\n10. تہٕ نہ صرف {یہ}؛ مگر ییلہ ربیکا تہِ اکس سٍتـ̡ حاملہ گومُت، {حتیٰ کہ} سٲنـ̡ مٲلۍ اسحاق سٍتـ̡\n11. (یێلہِ {بچہٕ} چُھہ نہٕ وُنیُک تام زامُت، تہٕ چُھہ نہٕ کانہہ نیکی تہٕ بُردی کٔرمٕژ، یُتھ زِ انتخابس مُطٲبق گژھہِ خدایہ سُند مقصد قایم سپدُن، نہ کامہِ سٍتـ̡ بلکہ یُس بلاوان چُھہ؛)\n12.\\tأمِس اوس وننہٕ آمُت زِ بٔڈۍ کرِ لۄکٹِس سٕنز خدمت۔ {بزرگ: یا، بڑ} {نوجوان: یا، کم}\n13.\\tیُتھ زن لیکھنہٕ آمُت چُھ، یعقوب چُھس میہ محبت کورمُت، مگر عیسیٰ سٍتـ̡ چُھس میہ نفرت۔\n14.\\tاسہِ کیا ونو تیلہِ؟ {کیا خدایس سٍتـ̡ چُھہ ناپاکیزگی؟ خدا نہ کرِ۔\n15.\\tیێلہِ سُہ چُھ موسیٰ ہس ونان زِ بہٕ کرٕ رحم یٔمِس پیٹھ بہٕ رحم کرِ، تہٕ بہٕ کرٕ رحم یٔمِس پیٹھ بہٕ رحم کرِ۔\n16.\\tتێلہِ چُھہ نہٕ تٔمِس سٍتـ̡ یُس مرضی کران چُھ، تہٕ نہ چُھہ یُس ژلان چُھ، بلکہ چُھہ خدایہ سٕندِ سٍتـ̡ یُس رحمتہٕ ہاوان چُھ۔\n17. صحیفہٕ چُھ فرعونس ونان زِ امی مقصدٕ خٲطرٕ تہِ چُھس مے ژے تۅہہ تھوٚد کٔرمٕژ، یُتھ بہٕ ژے سٍتـ̡ پنُن طاقت ہٲوِتھ، تہٕ سٲرۍسٕے زمینس منز گژھہِ میون ناو اعلان کرنہٕ۔\n18. تێمہِ کِنۍ چُھ أمِس سٍتـ̡ رحم کٔرِتھ تہٕ یێمِس سٍتـ̡ سُہ سختی کرِ۔\n19.\\tتیلہِ کٔرِو میہ ونُن، تس کیازِ چھہ وُنہِ تہِ عیب ژھانڈان۔ تکیازِ کمۍ چھہ تسنزِ مرضی خلاف مزاحمت کٔرمژ۔\n20. نہ، مگر اے انسان، ژے کُس چُھ یُس خدایس خلاف جواب دِوان چُھ؟ یُس چیز بنیوو، سہ ونن یُس بنوومت چھُ، ژے کیازِ چھکھ میہ یتھہ پاٹھۍ بنوومُت؟ {جواب...: یا، جواب دِیُن، یا خدایس سٍتۍ تنازعہٕ؟}\n21.\\tکیا میژِ پیٹھ چھا نہ کمہارن ہُند اختیار یُس أکِس بانس عزت دِتھ تہٕ بییِس بےٚ عزتی کٔرِتھ؟\n22.\\t{کیا} اگر خدایہ، پنن قہر ظٲہر کرنہٕ خٲطرٕ تہٕ پنُن طاقت ظٲہر کرنہٕ خٲطرٕ، تِمن ہٕندِس قہر ہٕندِس برتن سٍتۍ برداشت کرُن: {موزون: یا، بناوُن}\n23. تہٕ یُس سُہ رحمتٕکۍ بانن پیٹھ پننہِ عظمتٕچ دولت ظٲہر کرِ، یُس تٔمۍ گۅڈٕ جلال خٲطرٕ تیار کورمُت اوس،\n24.\\tاسہِ تہِ، یُس نہ صرف یہودین بلکہ غیر قومن ہُند تہِ بلاوُن؟\n25. یِتھ کٔنۍ سُہ اوسیس مَنٛز تہِ وَنُن چُھ، بہٕ وَنُن تِمن پنٕنۍ لوک، یِم نہٕ میٲنۍ لوٗکھ ٲسۍ۔ تہٕ تٔمۍ سُند معشوق، یُس نہٕ محبوب اوس۔\n26.\\tتہٕ یێلہِ سپدِ تَتھ جایہِ یێلہِ تِمن یہِ وننہٕ اوس آمُت، تُہۍ چھِو نہٕ میٲنۍ لوک۔ تتہِ یِن تِمن زندٕ خدایہِ سٕندِ اولاد وننہٕ۔\n27. یسیاس تہِ چُھ اسرٲیلِس مُتلق فریاد دِوان، یودوَے بنی اسرٲیلِن ہُند تعداد سمندرٕ کِس سیکہِ ہیوٗ آسہِ، مگر یێلہِ ہُند باقیات گژھہِ رژھراونہٕ یُن:\n28.\\tتکیازِ سُہ کرِ کٲم مُکمل تہٕ نیکی سٍتـ̡ ژٔٹِھتھ کٔرِتھ: کیازِ خداوند کرِ زمینس پیٹھ اکھ مختصر کٲم۔ {کٲم: یا، کھاتہٕ}\n29. تہٕ یِتھ کٔنۍ زَن عیسیٰ گۅڈٕ ووٚنمُت، سباعوتھُک رب اوس اسہِ اکھ بیول تروومُت، أسۍ ٲسۍ سڈوما ہٕندۍ پٲٹھۍ، تہٕ گومورہٕ ہٕندۍ پٲٹھۍ۔ {سباؤتھ: ہیب۔ میزبان}\n30. تیلہِ کیا ونو اسہِ؟ یہِ زِ غیر قومی، یِم نیکی پَتہٕ پَتہٕ پٲٹھۍ، چھِ نیکی حٲصِل کٔرمٕژ، حتیٰ کہ ایمانہٕ سٍتـ̡ تہِ چھِ نیکی حٲصِل کٔرمٕژ۔\n31. مگر اسرائیل، یُس نیکی ہٕندِس شریعت پَتہٕ پٲٹھۍ، چُھنہٕ نیکی ہٕندِس قانونس تام وٲتِتھ۔\n32. کیازِ؟ تکیازِ {تمو ژھانڈمُت} اوس نہٕ ایمانہٕ سٍتـ̡ بلکہ شریعت کِس کامہِ سٍتـ̡ ۔ تکیازِ تِمو گٔیہِ تتھ ٹھوکر کھسنہٕ کِس کٔنِس پیٹھ ٹھوکر۔\n33.\\tیِتھ کٔنۍ چُھہ لیکھنہٕ آمُت، وُچھِو بہٕ ساینَس مَنٛز اکھ ٹھوکر تہٕ جُرمٕچ پتھر، تہٕ یُس تہِ أمِس پیٹھ یقین کرِ، سُہ گژھِ نہٕ شرمندٕ۔ {شرمندہ: یا پریشان}","1. بھائیو، میانہِ دِلٕچ خٲہش تہٕ دُعا چُھ خدایہِ سٕندِ خٲطرٕ دُعا یُس تِم نجات دِنہٕ یِن۔\n2. تِکیازِ بہٕ چُھس تِمن ہُند درٕج دِوان زِ تِمن چُھ خدایہِ سُند جوش، مگر علمہٕ مُطٲبق چُھ نہٕ۔\n3. تِم چِھہ خدایہِ سٕنزِ نیکی نِش لاعلم آسنہٕ کِنۍ، تہٕ پنٕنۍ نیکی قایم کرنہٕ خٲطرٕ چُھہ نہٕ پنُن پان خدایہ سٕنزِ نیکی ہٕندِس تابع کرنہٕ آمُت۔\n4. عیسیٰ مسیح سٍتـ̡ چُھہ پریتھ کُنہِ ایماندارس سٍتـ̡ شریعتُک خاتمہٕ۔\n5. کیازِ موسیٰ چُھ سُہ نیکی بیان کران یُس شریعتُک چُھ، یُس انسان یِم کٲم کران چُھ، سُہ روزِ تِمن مطٲبق زندٕ۔\n6.\\tمگر یُس نیکی ایمانہٕ سٍتـ̡ چُھہ یێلہِ کتھ کران، پننِس دِلس مَنٛز کُس چُھہ وَنُن، کُس کرِ جنتس مَنٛز؟ (یعنی، مسیح سُند بۄن والُن}:)\n7. یا کُس گژھہِ سرٛنِس مَنٛز؟ (یعنی، مسیح سُند دُبارٕ زندٕ کرنہٕ خٲطرٕ۔)\n8. مگر یہ کیا چُھ ونان؟ لفظ چُھہ تۅہہِ نزدیک، تہٕ تُہندِس دلس مَنٛز، یعنی ایمانُک کلام، یُس أسۍ تبلیغ کران چھِ؛\n9. یێلہِ ژے پننہِ ٲسِس سٍتـ̡ خداوند عیسیٰ سُند اقرار کٔرِو، تہٕ پننِس دِلس مَنٛز پژھ کرِو زِ خداین چُھ سُہ مُردٕ پى۪ٹھہٕ زندٕ کورمُت، تێلہِ گژھہِ نجات حٲصل سپدٕنـ̡ ۔\n10. تِکیازِ انسان چُھ دِلہٕ سٍتـ̡ نیکی پٲٹھـ̡ پ تہٕ ٲسِس سٍتـ̡ چُھہ نجات دِنہٕ خٲطرٕ اقرار کرنہٕ یِوان۔\n11.\\tصحیفہ چھہ ونان زِ یُس تہِ تس پیٹھ ایمان تھاوان آسہِ سہ گژھہِ نہ شرمندہ گژھن۔\n12.\\tکیازِ یہودی تہٕ یونانِس مَنٛز چُھنہٕ کانہہ فرق، تکیازِ سارِنٕے سارِنٕے سٍتـ̡ چُھہ اکوے خداوند سارِنٕے سٍتـ̡ مالدار آسان یُس أمِس بُلاونہٕ یوان چُھ۔\n13. یُس تہِ خداوند سُند ناو پکار کرِ، سُہ گژھہِ نجات دِنہٕ۔\n14.\\tتیلہِ کِتھہ پٲٹھـ̡ کٔرِن تِمن سٍتـ̡ یٔمِس پیٹھ یِمو پژھ آسہِ نہٕ۔ تہٕ تم کِتھ کٔنۍ کرن تٔمِس پیٹھ یقین یٔمِس متعلق تمو نہٕ بوزمُت چُھ؟ تہٕ مبلغ ورٲے کِتھہ کٔنۍ بوزن؟\n15.\\tتہٕ تِم کِتھہ کٔنۍ کرِ تبلیغ، یوتام تم سوزنہٕ یِن؟ یِتھ کٔنۍ چُھ لیکھنہٕ آمُت، تِمن ہٕندِس قدمن کوتاہ خوبصورت چِھ یِم امنٕچ خوشخبری دِوان چھِ، تہٕ اصل چیزن ہٕنز خوشخبری دِوان چھِ!\n16. مگر یِمو سارِوٕے چُھنہٕ انجیل ہٕنز اطاعت کٔرمٕژ۔ یِکیازِ عیسیٰ چُھ ونان، خداوند، کُس چُھ سانہِ رپوٹ پژھ کٔرمُت؟ {سون رپورٹ: Gr. The Hearing of Us?} {رپورٹ: یا، تبلیغ؟}\n17. تێلہِ چُھ ایمان خدایہ سٕندِ کلامٕ سٍتـ̡ بوزنہٕ سٍتـ̡ تہٕ بوزنہٕ سٍتـ̡ سپدان۔\n18. مگر بہٕ چُھس ونان، کیا تِمو بوز نہٕ؟ آ پٔزۍ پٲٹھۍ، تِہٕنز آواز گٔیہِ سارِنٕے زمینس منز، تہٕ تِہٕندِ کلامَن ہٕندِس اندس تام۔\n19. مگر بہٕ چُھس ونان زِ اسرٲیلِس چھا نہٕ خبر؟ گۅڈٕ موسیٰ چُھ ونان، بہٕ کٔرٕ ژےٚ حسد کرنہٕ خٲطرٕ یِم نہٕ لوکھ چھِ، {تہٕ} أکِس بیوقوف قومہٕ سٍتۍ بہٕ ژےٚ شرارت کٔرِتھ۔\n20.\\tمگر عیسیٰ چُھ سٮ۪ٹھاہ بے باک، تہٕ وَنُن چُھس بہٕ تِمن ہٕندِس سٍتـ̡ لبنہٕ آمُت یِمو نہٕ مےٚ ژھاران چُھہ ۔ میہ آو تِمن برونہہ کُن ظٲہر کرنہٕ یِم نہٕ میانہِ پتہٕ پرژھان ٲسۍ۔\n21. مگر سُہ چُھ اسرٲیلِس ونان زِ سٲرۍسٕے دۅہہٕ چُھس بہٕ أکِس نافرمان تہٕ نافرمان لُکن کُن اتھہٕ پٔھلٲومُت۔","1. بہٕ چُھس ونان تیلہِ، کیا خداین کٔر پنٕنۍ لوک؟ خدا نہ کرِ۔ تکیازِ بہٕ تہِ چُھس اِسرٲیلِی، یُس ابراہیم سٕندِ نسلہٕ سٍتـ̡ چُھ، یُس بنیامین سٕندِس قبیلس سٍتـ̡ چُھس۔\n2. خداین کٔر نہٕ پَنٕنـ̡ پَنٕنـ̡ لُکھ یُس أمِس گۄڈے زانان اوس۔ کیا چھہ نہ صحیفہ الیاس سند وننہ آمت؟ سُہ کِتھہ پٲٹھـ̡ چُھہ اسرٲیلِس خلاف خدایہ سٕنز شفاعت کٔرِتھ ونان {elias: Gr. in Elias؟}\n3.\\tخداوند، تِمو چھُ تُہٕندِس پیغمبرن مٲرِتھ تہٕ تُہٕندِس قربان گاہٕ کھٔنِتھ کھٔنِتھ۔ تہٕ بہٕ چُھس کُنی روزان، تہٕ تِم چھِ میانہِ زندگی ژھاران۔\n4. مگر تس کیا چُھ خدایہِ سُند جواب دِوان؟ میہ چھِ پانس خٲطرٕ ستھ ساس نفر رژھرٲومٕتۍ، یِمو نہٕ بعل سٕنزِ تصویرس کُنہِ کۅٹھہٕ نِش نمُت چھِ۔\n5. توتہِ چُھہ ازکل تہِ فضل سٕندِ انتخابس مطٲبق اکھ باقیات موجود۔\n6. تہٕ یێلہِ فضل سٍتـ̡ چُھہ نہٕ یہِ زیادٕ کامہِ سٍتـ̡ کامہِ سٍتـ̡ کُنہِ تہِ فضل سٍتـ̡ چُھہ نہٕ زیادٕ فضل سپدان۔ مگر اگر یہ کامہِ ہند آسہِ، تیلہِ چھا نہ یہ کانہہ نعمت: نتہ چھیہ نہ کٲم کانہہ کٲم۔\n7. تیلہٕ کیا چُھ؟ اسرٲیلَن چُھ نہٕ سُہ حٲصِل کوٚرمُت یُس سُہ ژھاران چھُ۔ مگر انتخابن کور یہ حٲصل، تہٕ باقٕے گٔیہٕ انہٕ {انہٕ: یا، سخت}\n8.\\t(یتھہ پاٹھۍ لیکھنہ آمت چھہ زِ خداین چھہ تمن نندر ہند روح دژمُت، اچھ یُس نہ تم وچھن تہ کُن یُس نہ تم بوزُن پزِ نہ۔) از تام چھہ خداین دِژمُت۔ {نِندٕر: یا، پچھتاو}\n9. تہٕ داؤد چُھ ونان، تِہُند میز گژھہِ جال تہٕ جال تہٕ ٹھوکر تہٕ تِمن ہُند بدلہٕ بَناوُن:\n10.\\tتِمن ہٕنزِ أچھ گٔژھِن گٔژھِن، یُتھ نہٕ تِم وُچھِن تہٕ ہمیشہٕ پَنٕنہِ پَنُن پَنُن کُن نمُن۔\n11. بہٕ چُھس ونان، کیا تِم چھا ٹھوکر کھٲتِتھ زِ تِم پَزِ پَنُن؟ خدا نہ کرے: مگر {بلکہ} تہندِ زوال سٍتـ̡ نجات {چُھ} غیر قومن ہٕندِ خٲطرٕ، تکیازِ تِمن حسد کرنہٕ خٲطرٕ۔\n12. وۅنۍ یێلہِ یێلہِ یِمن ہٕندِس دُنیاہُک دولت تہٕ یِمن ہٕندِس دُنیاہس سٍتـ̡ کم سپدِ۔ تمن کوتاہ زیادٕ پورٕ؟ {کمی: یا، زوال، یا، نقصان}\n13. یێلہِ بہٕ چُھس تۅہہِ غیر قومن سٍتـ̡ کتھ کران، یێلہِ بہٕ چُھس غیر قومن ہُند رسول، بہٕ چُھس پنُن عہدٕ بڑاوان:\n14.\\tاگر بہٕ کُنہِ تہِ طریقہٕ سٍتـ̡ تِمن ہٕنز تقلید کرنٕچ ترغیب دِتھ یِم میون ماز چھِ، تہٕ یِمو منزٕ کینہہ بچٲوِتھ۔\n15.\\tیێلہِ یێلہِ یِمن ہٕندِس دُنیاہس سٍتـ̡ صلح کرنہٕ سٍتـ̡ کیا آسہِ، مگر مُردن سٍتـ̡ زندگی دِنہٕ؟\n16.\\tیێلہِ گۅڈنیُک پھل {چھُ} مُقدس، تہٕ اگر موٗل {be} مُقدس آسہِ، تیلہِ چھِ {مُقدس} تہِ۔\n17.\\tتہٕ یێلہِ کینہہ لنجہِ ژٹنہٕ یِن، تہٕ ژے یێلہِ جنگلی زیتون کُل آسنہٕ کِنۍ، تہٕ یِمن سٍتـ̡ زیتون کُلِچ موٗل تہٕ چربی ہُند حصہٕ آسہِ۔ {یمن منز: یا، تمن ہندِ خاطرہ}\n18.\\tلنجہِ خلاف کرو نہ شیخ۔ مگر اگر ژیہ فخر کران چھِو، تیلہِ چھُنہٕ تۅہہ موٗل بلکہ موٗل تہِ۔\n19.\\tتَمہِ وِزِ وَنُن زِ لٔرِ ژٔٹِتھ یُس بہٕ ژٔٹِتھ ژٔٹِتھ گٔیہِ۔\n20. اچھا؛ کُفر کِنۍ گٔیہِ تِم ژٹنہٕ، تہٕ تُہۍ چھِو ایمانس پیٹھ کھڑا روزان۔ تھدِ نہ کرُن، بلکہ گژھہِ خوف:\n21. تکیازِ اگر خدایہ فطری لنجہِ بچاوِ نہ، {دھیان تھاوُن} نتہ گژھہِ نہ تۅہہ تہِ بخش۔\n22.\\tتێلہِ وُچھِو خدایہِ سٕنز نیکی تہٕ شدت: یِمن پى۪ٹھ، یِمن پى۪ٹھ، سٍتـ̡ سختی مگر ژے کُن، نیکی، اگر تہٕ تٔمۍ سٕنزِ نیکی منز جٲری روزِو، نتہٕ گژھہِ ژے تہِ ژٹنہٕ۔\n23. تہٕ تِم تہِ، یێلہِ تہِ یِم کُفر کُن روزِ، تێلہِ یِن دُبارٕ کُنـ̡ دِنہٕ یِنـ̡ پى۪ٹھ۔\n24. یێلہِ ژے زیتون کُلِس سٍتـ̡ ژٹنہٕ یِیہِ یُس فطرتس سٍتـ̡ جنگلی چُھ، تہٕ قۄدرتس برعکس أکِس اصل زیتون کُلِس مَنٛز ژٔٹِتھ یِیہِ، یِم کوتاہ بییہ یِن پننِس زیتون کُلِس مَنٛز ژٔٹِتھ دِنہٕ۔\n25. تکیازِ بہٕ چُھس نہٕ یێلہِ زِ تۅہہِ گژھہِ اتھ اسرارس نِش لاعلم، یێلہِ گژھہِ تۅہہ پننین غرورن مَنٛز عقلمند بٔنِتھ۔ یہِ چھُ اِسرٲیلِس سٍتـ̡ اَنُن سپدُن، یوتام نہٕ غیر قومن ہُند مکمل آسن یِن۔ {انہِ پن: یا، سختی}\n26. تہٕ یِتھٕ پٲٹھـ̡ یێلہِ سارِنٕے اسرٲیلـ̡ بچاونہٕ یِنـ̡ یێلہِ چُھہ لیکھنہٕ آمُت، سِیون سٍتـ̡ نجات دِنہٕ وٲلِس سٍتـ̡ نیرِ، تہٕ یعقوب نِش گژھہِ بے دینی پتھ کُنـ̡ ۔\n27. یێلہِ چُھہ تِمن سٍتـ̡ میٲنۍ عہد ، یێلہِ بہٕ تِہُند گۅناہ دور کٔرِ۔\n28.\\tانجیل سٍتـ̡ چِھہ {تِم چِھہ} تُہٕندِ خٲطرٕ دشمن: مگر یێلہِ چُھہ انتخابس سٍتـ̡ {تِم﴾ مٲلن ہٕندِ خٲطرٕ ٹٲٹھـ̡ ۔\n29.\\tخدایہ سٕندِ تحفہٕ تہٕ بلاوُن چُھہ توبہ ورٲے ۔\n30. یِتھ کٔنۍ زَن پتھ کالس مَنٛز چُھہ نہٕ خدایس پیٹھ ایمان تھاوان، توتہِ چُھکھ تِہندِ کُفر سٍتـ̡ رحم حٲصل کٔرمُت: {پژھہٕ: یا، اطاعت کٔرِتھ}\n31. توتہِ چُھہ نہٕ یِمن تہِ وُنہِ پژھ پٲٹھۍ، زِ تُہٕندِ رحمتہٕ سٍتـ̡ ہیکن تِم تہِ رحم حٲصل کٔرِتھ۔ {پژھ: یا، اطاعت کٔر}\n32.\\tکیازِ خداین چُھ یِمن سارِنٕے کُفر کُن ختم کورمُت، یُتھ زن سُہ سارِنٕے سٍتـ̡ رحم کرُن۔ {نتیجہ...: یا، یم سٲری کٔرِو یکوٹہ بند}\n33. اے خدایہ سٕنز حکمت تہٕ علمہٕ دۄشوٕے ہٕنز گہرایی ! تٔمۍ سٕندۍ فیصلہٕ کوتاہ چھِ نہٕ تلاش کٔرتھ، تہٕ تٔمۍ سٕندِ وتہٕ پتھ کُن ژھانڈنہٕ یِنہٕ وٲلۍ!\n34. کیازِ خداوند سُند ذہنس کُس چُھ زانان؟ یا کُس چُھ تٔمۍ سُند مُشیر روٗدمُت؟\n35.\\tیا کٔمۍ چُھ أمِس گۄڈنِچہِ لٹہِ دِتمُت، تہٕ أمِس یِیہِ دُبارٕ بدلہٕ دِنہٕ؟\n36. تکیازِ أمِس سٍتـ̡ تہٕ أمِس سٍتـ̡ تہٕ أمِس سٍتـ̡ چُھہ سارِنٕے چیز: یٔمِس سٍتـ̡ ہمیشہٕ خٲطرٕ جلال آسہِ۔ آمین۔ {whom: Gr. him}","1. بہٕ چُھس تۅہہِ خدایہ سٕنزِ رحمتہٕ سٍتـ̡ التجا کران زِ تُہۍ کٔرِو پَنٕنـ̡ پَنٕنـ̡ زندٕ قربانی دِنہٕ، پاک، خدایہِ سٕندِ خٲطرٕ قبول، {یُس} تُہٕنز معقول خدمت چُھ۔\n2. تہٕ گژھِو نہٕ یتھ دنیاہس سٍتـ̡ مطابقت تھاوان، بلکہ گژھِو پَنٕنـ̡ دٮ۪ماغٕچ تجدید سٍتـ̡ تبدیٖل گٔژِھتھ یُتھ زِ خدایہِ سٕنز مرضی کیا چُھ، تہٕ قبول۔\n3. تکیازِ بہٕ چُھس ونان زِ میہ دِنہٕ آمٕژ فضل سٍتـ̡ یُس تہٕ تۅہہِ منز موجود پریتھ انسانس سٍتـ̡ سُہ کرِ نہٕ پننِس بارس مُتعلِق زیادٕ سونٛچُن۔ مگر سنجیدگی سان سونچُن، یتھہ پاٹھۍ خداین پریتھ انسانس سیتۍ ایمانک پیمانہ ورتاومت چھہ۔ {سنجیدگی سان: Gr. to Soberriety}\n4. تکیازِ اسہِ چھہ اکس جسمس منز واریاہ ارکان، تہٕ سارنٕے ارکانن چھہ نہ اکوے دفتر:\n5. یێلہِ چُھہ أسـ̡ {واریاہ آسنہٕ کِنـ̡ مسیحس مںز اکھ جسم، تہٕ پرٮ۪تھ اکھ اکھ رُکُن چُھہ اَکھ أکِس سٍتـ̡ ۔\n6. یُس فضل اسہِ دِنہٕ آمُت چُھ، یُس پیشن گویی آسہِ، {اسہِ کرو پیشن گوئی} ایمانہٕ کِس تناسبس مطٲبق۔\n7. یا خدمت، {اسہِ پرارُن} سٍتـ̡ پرناوُن: یا یُس ہیچھناوان چُھہ، سُہ چُھہ پرناوُن؛\n8. یا یُس نصیحت دِوان چُھ، یُس دِوان چُھ، سُہ کرُن سادگی سٍتـ̡ ۔ سُہ یُس محنتہٕ سان حکمرٲنی کران چُھ؛ سُہ چُھ یُس رحمتہٕ سٍتـ̡ خوش گٔژھان چُھ۔ {دِن: یا، دِنہٕ} {سادگی سان: یا، فراخ دلی سان}\n9. {گژھہِ} محبت گژھہِ بے قراری ورٲے آسُن۔ یُس بد کار چھُ، تتھ سٍتۍ کرو نفرت۔ تتھ چیزس سیتۍ رٔٹتھ یُس اصل چُھ۔\n10.\\tاَکھ أکِس سٍتـ̡ بٲے سٍتـ̡ محبت۔ عزت دِتھ اکھ أکِس ترجیح دِنہٕ؛ {سٍت...: یا، بٲے سٕندِس محبتس منز}\n11. کاربارس منز چُھ نہٕ سُست ۔ روحس منز جوش؛ خداوند سٕنز خدمت کرٕن؛\n12. وۅمید سٍتـ̡ خوش گژھُن؛ مصیبت منٛز مریض؛ دعاہس منز فوراً جٲری؛\n13. مقدسن ہٕنزِ ضرورتس منز تقسیم کرُن؛ مہمان نوازی دِنہٕ آمُت۔\n14. یِمن سٍتـ̡ تُہٕندِس عذابَس سٍتـ̡ دِیُو: دُعا کٔرِو تہٕ بد دعا کٔرِو۔\n15. یِمن سٍتـ̡ خوش سپدان چُھ، تہٕ رووُن تِمن سٍتـ̡ روُن۔\n16.\\tاکۍ سے ذہنس منز اکھ بییِس کُن آسُن۔ تھدِ چیزن ہُند خیال تھاوُن نہٕ بلکہ کرو کم جایداد والین نفرن ہٕنز حقارت ۔ پننین غرورن منز گژھہِ نہ دانشمند۔ {condes...: یا، مضحکہ خیز چیزن پیٹھ گژھ مطمئن}\n17. بدی ہُند بدلہٕ کُنہِ تہِ انسانس سُند بدلہٕ۔ سارِنٕے انسانن ہٕندِس نظرِ منز کٔرِو ایماندارانہ چیز فراہم۔\n18.\\tاگر یہ ممکن آسہِ، یوت یوت تہِ ژیہ پانس منز روزِ، تیلہِ روزو سارنٕے انسانن سٍتـ̡ سٍتـ̡ سکون سان روزُن۔\n19.\\tپیاری محبوب، پانس سٍتۍ کرو نہ انتقام، بلکہ دِیُن غضبٕچ جاے: تکیازِ یہ چھُ لیکھنہٕ آمُت، انتقام {چُھ} میون خداوند چُھس ونان زِ بہٕ کٔرٕ بدلہٕ۔\n20. لہٰذا اگر تُہُند دُشمن فاقہٕ آسہِ، تٔمِس کھیٚنہٕ دِیُن۔ اگر أمِس تریش آسہِ، تیٚلہِ دِیِو أمِس چیٚنہٕ، تِکیازِ یِتھٕ پٲٹھۍ دِیُو تٔمِس کَلَس پٮ۪ٹھ نارٕکۍ کولہٕ ڈھیرٕ۔\n21.\\tبدی پیٹھ گژھِ نہٕ غلبہ حٲصل سپدِتھ بلکہ گژھہِ نیکی سٍتۍ بدی پیٹھ قابو پیوان۔","1. پرتھ کانہہ روح گژھہِ اعلیٰ طاقتن تابع کرنہ۔ تکیازِ خدایہ سٕندِ سوا چُھ نہٕ کانہہ طاقت: یُس طاقتہٕ چُھ خدایہ سٕندِ طرفہٕ مقرر کرنہٕ آمُت۔ {مقرر: یا، حکم دِنہٕ}\n2. یُس تہِ طاقتس خلاف مزاحمت کرِ، سُہ چُھ خدایہ سٕندِس حکمس خلاف تہٕ یُس مزاحمت کران چُھ، سُہ چُھ پانس سٍتـ̡ سزا دِنہٕ۔\n3.\\tحکمرانن ہٕندِ خٲطرٕ چُھنہٕ نیک کامین ہُند دہشت بلکہِ بد سٍتـ̡ بدی ہٕندِ خٲطرٕ۔ تیلہِ گژھہِ نہ ژیہ طاقتہ نشہِ کھوژان؟ سُہ کٔرِو یُس اصل چُھ، تہٕ توے گژھہِ اَمہ سٕنز تعریف:\n4. تکیازِ سُہ چُھ تۅہہِ خٲطرٕ خدایہِ سُند وزیر۔ مگر اگر تۅہہ بدکار کٲم کرِ، تیلہِ گژھہِ کھوژُن۔ تکیازِ سُہ چُھ نہٕ تلوار بیکار تُلان، تکیازِ سُہ چُھ خدایہِ سُند وزیر، یُس بدکار کران چُھس تٔمِس پیٹھ قہر دِنُک انتقام چُھ۔\n5.\\tلہذا گژھہِ نہ صرف غصہ خاطرہ بلکہ ضمیرس خاطرہ تہِ تابع آسنچ ضرورت۔\n6.\\tامہِ مۅکھہ تہِ چھِو تۅہہ خراج تہِ دِوان: تکیازِ تِم چھِ خدایہ سٕندِ وزیر، یِم اتھ چیزس پیٹھ مسلسل توجہ دِوان چھِ۔\n7. تَمہِ کِنۍ کٔرِو تِہٕندِس سارِنٕے قٕسمَس دِیُن: خراج دِیُن یُس خراج {واجب چھُ}؛ رسم و رواج کس خٲطرٕ؛ خوفہٕ کُس خوفہٕ؛ عزت، کُس عزت۔\n8. کٲنسہ تہِ کرُن کانہہ تہِ مقروض، مگر اکھ أکِس سٍتـ̡ محبت کرُن، تکیازِ یُس بییِس سٍتـ̡ محبت کران چُھ، سُہ چُھ شریعت پورٕ کٔرمٕژ۔\n9.\\tاَمہِ مۅکھہٕ گژھِ نہٕ زنا کٔرِتھ، ژے گژھِ نہٕ قتل کٔرِتھ، ژٕ گژھِ نہٕ ژوٗرِ کٔرِتھ، تہٕ ژٕ گژھِ نہٕ اپُز گوٲہی دِنہٕ، تہٕ ژٕ گژھِ نہٕ لالچ کٔرٕنۍ۔ تہٕ اگر بییہ کانہہ حکم آسہِ، تیلہِ چھہ یہ مختصر پاٹھۍ اتھ قولس منز سمجنہ آمت، یعنی ژے کرِ پننس ہمساین پانس سیتۍ محبت کرُن۔\n10.\\tمحبت چھہ نہ ہمساین سٍتـ̡ کانہہ بد کار کران، تێمہِ مۅکھہ چُھہ محبت شریعتٕچ تکمیل سپدان۔\n11. تہٕ یہِ زٲنِتھ زٲنِتھ زِ وُنۍ چُھ نِندرِ منزٕ بیدار گژھنُک وق تہٕ وُنـ̡ چُھہ سون نجات یێلہِ سٍتـ̡ أسـ̡ پژھہٕ پٲٹھـ̡ پى۪ٹھ۔\n12.\\tرٲژ گُزراونہٕ آمٕژ، دۅہ چُھ اتھہٕ پیٹھ: تێمہِ کِنۍ کرو أسۍ انہِ گٹہِ ہٕنزِ کٲم ترٲوِتھ تہٕ گاشُک ہتھیار لاگُن۔\n13. اسہِ پٔکِو ایمانداری سان پَکُن، یِتھٕ پٲٹھۍ دۅہہٕ پٲٹھۍ۔ نہ فساد تہٕ شرابس منٛز، نہ چیمبرنگ تہٕ بے راہ روی منٛز، نہ جھگڑس تہٕ حسدس منٛز۔ {ایمانداری: یا، مہذب}\n14. مگر خداوند عیسیٰ مسیحس پیٹھ تھوو، تہٕ مازس خٲطرٕ مہٕ رژھ رژھ رٔٹِو، یُس ہوس پورٕ کرنہٕ مۅکھہٕ۔","1. یُس ایمان مَنٛز کمزور چُھ، سُہ چُھ نہٕ شَکَس سٍتـ̡ قبول کٔرِتھ۔ {نہ...: یا، نہ تہندس مشکوک خیالن ہند فیصلہ کرُن}\n2.\\tیُس یُس یُس کمزور چُھ، سُہ چُھ جڑی بوٹی کھیوان۔\n3. یُس نہٕ کھٮ۪وان چُھ، سُہ گژھِ نہٕ تٔمِس حقارت کٔرِتھ یُس نہٕ کھٮ۪وان چُھ۔ تہٕ یُس کھٮ۪وان چُھ، سُہ گژھِ نہٕ کھٮ۪وان تٔمِس سُند فیصلہ کرُن، کیازِ خداین چُھ سُہ قبول کوٚرمُت۔\n4. ژٕ کُس چُھکھ یُس بییِس انسان سٕندِس خادمُک فیصلہ کران چُھ؟ سُہ چُھ پننِس آقا سٕندِس سٍتـ̡ کھڑا سپدان یا پیوان ۔ آ، سُہ گژھہِ تھپھ کٔرِتھ: تکیازِ خدایہ چُھ تس کھڑا کرنس لایق۔\n5.\\tاَکھ شخٕص چُھ أکِس دۅہس بییِس دۅہس پیٹھٕ احترام تھاوان: بیاکھ چھُ پریتھ دۅہس ہِوُے احترام کران۔ پریتھ انسان گژھہِ پننِس ذہنس منز پورٕ پٲٹھۍ۔ {مکمل طور مطمعین: یا، مکمل یقین دہانی}\n6. یُس دۅہہُک خیال تھاوان چُھ، سُہ چُھ خداوند سُند خیال تھاوان؛ تہٕ یُس نہٕ دۅہُک خیال تھاوان چُھ، سُہ چُھ نہٕ خداوند سُند خیال تھاوان۔ یُس کھٮ۪وان چُھ، سُہ چُھ خدایہِ سُند شُکر ادا کَران۔ تہٕ یُس نہٕ کھٮ۪وان چُھ، سُہ چُھ نہٕ خداوند سُند شُکر کَران۔ {حوالہٕ: یا، مشٲہدٕ}\n7. تکیازِ اسہِ منزٕ چُھہ نہٕ کانہہ تہِ پانس سٍتـ̡ زندٕ روزان، تہٕ کانہہ تہِ انسان چُھہ نہٕ پانس سٍتـ̡ مران۔\n8. یێلہِ أسـ̡ زندٕ روزو، أسـ̡ چِھہ خداوند سٕندِ سٍتـ̡ زندٕ۔ تہٕ اگر أسۍ مران چھِو، أسۍ چھِ خداوند سٕندِ خٲطرٕ مران۔\n9. یێمہِ مۅکھہٕ مسیح دۅشوے مٔرِتھ تہٕ زندٕ سپدُن تہٕ زندٕ سپدُن، یُتھ سُہ بٔنِتھ مرُن تہٕ زندٕ دۄشوٕنی ہُند خداوند بٔنِتھ۔\n10.\\tمگر ژیہ کیازِ چُھکھ پننِس بٲے سُند فیصلہ کران؟ نتہٕ کیازِ چُھکھ پنُن بٲے کُنہِ تکیازِ أسۍ سٲری گژھو مسیح سٕندِس عدالتس برونہہ کُن۔\n11.\\tیِہ چُھہ لیکھنہٕ آمُت، {یێلہِ} چُھس زِندٕ روزان، خداوند چُھ ونان زِ پرٮ۪تھ کُٹھہِ گٔیہِ میانہِ برونہہ کُن نمُن، تہٕ پرٮ۪تھ کانہہ زبان کرِ خدایہِ سُند اقرار کرنہٕ۔\n12. تێلہِ گژھہِ اسہِ منزٕ پرٮ۪تھ کانہہ خدایہ سٍتـ̡ پنُن حساب دِنہٕ۔\n13.\\tتێلہِ گژھہِ نہ اسہِ اکھ أکِس سٍتـ̡ فیصلہ کرُن، بلکہ کرو یہ فیصلہ زِ کانہہ تہِ انسان گژھہِ نہ پننِس بٲے سٕندِس وتہِ منز رُکاوٹ یا موقعہٕ تراوُن۔\n14. بہٕ چُھس زانان، تہٕ خداوند عیسیٰ سٕندِ طرفہٕ چُھس یقین دِنہٕ آمُت، زِ یُس کُنہِ تہِ چیزس ناپاک مانان چُھ، تٔمِس خٲطرٕ چُھ سُہ ناپاک آسان۔ {ناپاک: Gr. common}\n15.\\tمگر اگر تُہند بٲے تُہٕندِس مازس سٍتـ̡ غمگسار آسہِ، تێلہِ چُھہ نہٕ وۅنۍ تہٕ چُھہ نہٕ خیرات کٔرِتھ۔ یٔمِس خٲطرٕ مسیح موٗدمُت چھُ، سُہ گژھ نہٕ پنہٕ نِس ماز سٍتـ̡ تباہ کرنہٕ۔ {خیراتی طور پٲٹھۍ: Gr. مطابق خیرات}\n16.\\tتیلہِ گژھہِ نہ پننہِ نیکی ہنز کتھ کرنہٕ یُن:\n17. کیازِ خدایہِ سٕنز بادشٲہی چُھہ نہٕ ماز تہٕ چُھہ چُھہ نہٕ۔ مگر پاکیزگی، تہٕ امن تہٕ روح القدس سٕنز خوشی۔\n18.\\tیُس یُس یِمن چیزن مَنٛز مسیح سٕنز خدمت کران چُھ، سُہ چُھ خدایہ سٕندِ خٲطرٕ قبول، تہٕ انسانن ہٕندِ خٲطرٕ منظوٗر۔\n19. تێمہِ کِنۍ کرو أسۍ تِمن چیزن ہٕنز پیروی یِم امن بناوان چھِ، تہٕ یِمو سٍتـ̡ اکھ أکِس بییِس تعلیم دِوان چھِ۔\n20. ماز خٲطرٕ گژھ نہٕ خدایہ سٕنز کٲم تباہ کرنہٕ۔ سٲری چیز چھہِ پزۍ پاٹھۍ خالص آسان۔ مگر {یہ} چُھ تٔمِس شخصہٕ سٕندِ خٲطرٕ بُرٕ یُس بُرٕ چُھ کھٮ۪وان۔\n21.\\tماز کھیوٚن تہٕ شراب، تہٕ نہ چُھہ کانہہ تہِ چیز یتھ سٍتۍ تُہند بٲے ٹھوکر کھسِتھ یا ناراض گژھہِ، یا کمزور گژھہِ۔\n22. کیا تُہۍ چھوا ایمان؟ خدایہ سٕندِ برونہہ کُن تھاوُن پانس سٍتـ̡ خوش باش چُھ سُہ یُس نہٕ اتھ چیزس منز پانس مذمت کران چُھ، یُس سُہ اجازت دِوان چُھ۔\n23.\\tیُس شک کرُن چُھہ سُہ کھٮ۪وان چُھہ تہٕ سُہ چُھ نہٕ ایمانہٕ سٍتـ̡ کھٮ۪وان تہٕ یێلہِ تہِ چُھ نہٕ گۅناہ۔ {شک چھُ: یا، مازس درمیان فرق سمجھان تہٕ تھاوُن} {لعنتی: یا، مذمت، یا سزاہک ذمہ دار}","1.\\tاسہِ پزِ یُس مضبوط چھہِ تمن پزِ کمزورن ہنز کمزوری برداشت کرنۍ تہ پانس خوش کرُن نہ۔\n2.\\tاسہِ منز گژھہِ پریتھ کانہہ ہمساین خوش کرُن۔\n3. تکیازِ عیسیٰ مسیح تہِ اوس نہٕ پانس خۅش کران۔ مگر، یِتھ کٔنۍ لیکھنہٕ آمُت چھُ، تِمن ہٕنز ملامت یِمو ژےٚ ملامت کٔر سُہ گٔیہِ میہ پیٹھ۔\n4. یُس تہِ چیز برونہہ کنہِ لیکھنہٕ آمُت اوس، سُہ اوس سانہِ تعلیمہٕ خٲطرٕ لیکھنہٕ آمُت، یُتھ أسۍ صحیفہٕ کِس صبرس تہٕ آرام سٍتـ̡ وۅمید کٔرِتھ۔\n5. وۅنۍ چُھ صبر تہٕ تسلی دِنُک خدا مسیح عیسیٰ سٕندِ مُطٲبق اَکھ أکِس سٍتـ̡ ہِشر روزُن: {مُطٲبق: یا، مثالہٕ پٲٹھۍ}\n6. یُتھ زِ تُہۍ کٔرِو اَکہِ دٮ۪ماغہٕ سٍتـ̡ خدایہِ سٕندِس مٲلِس سٍتـ̡ تسبح کٔرِتھ۔\n7. تێلہِ کٔرِو اَکھ أکِس قبوٗل کٔرِو، یِتھ کٔنۍ مسیحن تہِ چُھ اسہِ خدایہِ سٕندِ جلال سٍتـ̡ قبول کٔرِتھ۔\n8. وۅنۍ چُھس بہٕ ونان زِ عیسیٰ مسیح اوس خدایہ سٕنزِ حقیقتہٕ خٲطرٕ ختنہ کرنُک وزیر، یُس مٲلن سٍتـ̡ کرنہٕ آمُت وعدن ہُند تصدیق کرنہٕ مۅکھہٕ:\n9. تہٕ یُتھ زن غیر قومن ہٕندِ رحمتہٕ خٲطرٕ خدایہ سٕنز حمد کٔرِتھ۔ یِتھٕ پٲٹھۍ چُھس لیکھنہٕ آمُت، اَمہ مۅکھٕ کٔرٕ بہٕ ژے غیر قومن مَنٛز اقرار تہٕ تہٕ گٮ۪وٕ تُہند ناو۔\n10. تہٕ بییہِ چُھ سُہ ونان زِ اے غیر قومن سٍتـ̡ پنہٕ نِس لُکہٕ سٍتـ̡ خوش گژھُن۔\n11. تہٕ دُبارٕ کٔرِو خداوند سٕنز تعریف، اے سارِنٕے غیر قومی۔ تہٕ تٔمِس تعریف، تم سارِوٕے لوکو۔\n12. تہٕ بییہِ چُھہ یسیاہس ونان زِ یسیٰ سُند موٗل آسہِ، تہٕ یُس غیر قومن پیٹھ بادشاہت کرنہٕ خٲطرٕ وۅتھنہٕ ییہِ۔ تٔمِس پیٹھ گژھِ غیر قومن ہُند بھروسہٕ۔\n13. وۅنۍ چُھہ وۅمید ہُند خدا یُس یژھہِ سٍتـ̡ وۅمید سٍتـ̡ بٔرِتھ تہٕ سُہ چُھہ روٝحہِ پاک سٕندِ طاقتہٕ سٍتـ̡ وۅمید حٲصل سپدِتھ۔\n14. تہٕ بہٕ چُھس پانہٕ تہِ ژےٚ ہٕندِس بارس مُتلق یقین دِوان زِ تُہۍ تہِ چھِو نیکی سٍتـ̡ بٔرِتھ، سارِوٕے علمہٕ سٍتـ̡ بٔرِتھ تہٕ اکھ أکِس نصیحت دِنس قٲبل۔\n15. بہر حال، بھائیو، مے چُھہ ژےٚ کُنہِ نتہٕ کُنہِ قٕسمس منز لیوکھمُت، یُس خدایہ سٕندِ فضل سٍتـ̡ دِنہٕ آمُت چُھ،\n16. زِ بہٕ گژھہِ عیسیٰ مسیح سُند وزیر بنُن، یُس خدایہِ سٕنزِ انجیل ہٕنز خدمت کرُن، یُتھ زن غیر قومن ہٕنز قربانی گژھہِ قابل قبول تہٕ روح القدس سٕندِ سٍتـ̡ پاک سپدِ۔ {پیش کرُن: یا، قربانی}\n17. تێمہِ کِنۍ چُھس بہٕ عیسیٰ مسیح سٕندِ ذریعہٕ تِمن چیزن مَنٛز جلال کٔرِتھ یِم خدایس سٍتـ̡ وابستہٕ چھِ۔\n18. کیازِ بہٕ ہیوٚک نہٕ تِمن چیزن مُتلق کُنہِ تہِ کتھ کرنٕچ ہمت کٔرِتھ یُس نہٕ عیسیٰ مسیحن میانہِ دٔسۍ کٔرۍمٕتۍ، غیر قومن ہٕندِ فرمانبردار بناونہٕ خٲطرٕ، کلامٕ تہٕ عملہٕ سٍتـ̡\n19. طاقتور نشانو تہٕ عجائبات سٍتـ̡ خدایہ سٕندِ روٝحہٕ سٕندِ طاقتہٕ سٍتـ̡ یُتھ یروشلم پیٹھٕ تہٕ اِلیریکم تام چُھ، مے چُھ مسیح سٕنز انجیل پورٕ پٲٹھـ̡ تبلیغ کٔرمٕژ۔\n20. آ، یێلہِ چُھہ میہ انجیل ہنز تبلیغ کرنٕچ کوشش کٔرمٕژ، یێلہِ نہٕ یێلہِ مسیح سُند ناو اوس دِنہٕ آمُت، یێلہِ بہٕ کُنہِ بییِس انسانہٕ سٕنزِ بُنیادس پیٹھ تعمیر کرُن:\n21.\\tمگر یُتھ زن یہ لیکھنہٕ آمُت چُھ، یٔمِس سٍتـ̡ أمِس سٍتـ̡ کتھ ٲس نہٕ کرنہٕ آمٕژ، تِم گژھن وُچھن: تہٕ یِم نہٕ بوزمُت آسہِ، تِم گژھن سمجُن۔\n22.\\tییمہ وجہہ کنۍ تہِ چھُس میہ ژے نِش یِنس منز واریاہ رُکاوٹ آمُت۔ {زیادٕ: یا، واریاہ طریقہٕ، یا اکثر}\n23.\\tمگر وۅنۍ چھیہ نہ یمن حصن منز کانہہ جاے، تہٕ یِمن ؤرین تام یِنُک سٮ۪ٹھاہ خٲہش۔\n24. ییلہ بہٕ سپینُک سفر کرِ، بہٕ یِیہٕ ژے نِش: تکیازِ بہٕ چُھس پننِس سفرس منز ژے وُچھن، تہٕ ژے ہٕندِ طرفہٕ یِنہٕ یِنہٕ واجنہِ وتہِ پیٹھ، اگر گۅڈٕ بہٕ چانہِ صحبتہٕ سٍتۍ بٔرِتھ آسہِ۔ {with...: Gr. with you}\n25. مگر وۅنۍ چُھس بہٕ یروشلم گژھان مُقدسن ہٕنز خدمت کرنہٕ خٲطرٕ۔\n26. تِکیازِ مقدونیہ تہٕ اخایا ہٕندِس یِمن غریبن ہٕندِ خٲطرٕ یِم یروشلمس مَنٛز چھِ۔\n27.\\tیہ چھہ تمن خۅش کران۔ تہٕ تِمن ہٕندِس قرضدار چھِ۔ یێلہِ یێلہِ غیر قومن ہٕندِس روٝحٲنی چیزن مَنٛز شریک آسہِ، تِمن ہُند فرض تہِ چُھ یِمن ہٕنزِ جِسمٲنی چیزن مَنٛز خدمت کرٕنـ̡ ۔\n28. تێلہِ ییلہ میہ یہ انجام دِژ، تہٕ تمن یہ پھل مہرٕ کرُن، بہٕ ییہ ژے سٍتـ̡ سپینس منز۔\n29. تہٕ مےٚ چُھ یقین زِ یێلہِ بہٕ یێلہِ تہٕ یێلہِ بہٕ یێلہِ تہٕ یێلہِ بہٕ یِیہٕ مسیح سٕنزِ انجیل ہٕنزِ برکتٕچ پوٗرٕ پٲٹھۍ۔\n30. وۅنۍ چُھس بہٕ ژے خدایہِ عیسیٰ مسیح سٕندِ خٲطرٕ تہٕ روٝحہِ سٕنزِ محبتہٕ خٲطرٕ التجا کران زِ تُہۍ کٔرِو میانہِ خٲطرٕ خدایہِ سٕنزِ دُعاہس مَنٛز رٔلِتھ کوشش کٔرِو۔\n31.\\tیُتھ بہٕ گژھہِ تِمن نِش نجات دِنہٕ یِم نہٕ یہوداہس پیٹھ یقین تھاوان چھِ۔ تہٕ یُس میٲنۍ خدمت یُس یروشلم خٲطرٕ چُھہ مُقدسن ہٕندِ طرفہٕ قبول کرنہٕ یُن۔ {نَہ کٔرِو...: یا، چھِ نافرمان}\n32.\\tیُتھ بہٕ گژھہٕ خدایہ سٕنزِ مرضی سٍتـ̡ ژے نِش خوشی سان واتہٕ، تہٕ ژے سٍتـ̡ روزٕ تازٕ۔\n33.\\tوۅنۍ گژھہِ امن ہند خدا۔ آمین۔","1. بہٕ چُھس ژے سٲنۍ بینہِ فیبی سٕنز تعریف کران، یۄسہٕ کلیساہٕچ خدمتگار چِھ، یۄسہٕ سینکریاہس مَنٛز چِھ:\n2. یێلہِ تہٕ یێلہِ تہٕ تٔمِس کُنہِ تہِ کارٕبارس مَنٛز تہٕ تٔمِس کُنہِ تہِ کارٕبارس مَنٛز مدد کٔرِو، تِکیازِ سُہ چُھہ واریاہن ہٕندِس مددگارس تہٕ میانہِ سٍتـ̡ تہِ مدد کٔرمٕژ۔\n3. مسیح عیسیٰ ہس منز میانین مددگارن پرسکیلا تہٕ عقیلہ سلام کرُن:\n4. یِمو میانہِ زندگی خٲطرٕ پنٕنۍ گردن ترٛٲومٕژ چھِ: یِمن ہُند نہ صرف بہٕ شُکر ادا کران چُھس، بلکہِ غیر قومن ہٕندِس سارنٕے گرجا گھرن تہِ۔\n5. یِتھے پٲٹھـ̡ چُھہ کلیساہس مَنٛز یُس تہندِس گرس مَنٛز چُھ۔ میٲنِس پیاری ایپینیٹسس کٔرِو سلام، یُس مسیحس خٲطرٕ اخایا سُند گۄڈنیُک پھل چُھ۔\n6.\\tمریم سلام کرُن، یمۍ اسہِ واریاہ محنت کٔر۔\n7. اینڈرونیکس تہٕ جونیا، میانین رشتہٕ دارن تہٕ میانین سٲتھی قٲدَن سلام، یِم رسولن مَنٛز قٲبلِ ذِکر چھِ، یِم میانہِ برونہہ مسیحس منز ٲسۍ۔\n8. ایمپلیاسس کٔرِو رب سٕندِس پیاری سٍتـ̡ سلام۔\n9. عیسیٰ مسیحس منز سٲنـ̡ مددگار، تہٕ سٹاچیسس سٍتـ̡ کٔرِو سلام۔\n10. عیسیٰ مسیحس مَنٛز منظوٗر کرنہٕ آمٕژ ایپیلس سلام۔ تِمن کٔرِو سلام یِم ارسطوبولس سٕندِس {گرٕکِس} سٍتـ̡ چھِ۔ {گھر: یا، دوس}\n11. ہیروڈینس سُند سلام کٔرِو میانِس رشتہ دار۔ تِمن کٔرِو سلام یُس نرسیسس سٕندِس {گرَس} سٍتـ̡ آسہِ، یِم خداوند سٕندِس سٍتـ̡ چھِ۔ {گھر: یا، دوس}\n12. ٹریفینا تہٕ ٹریفوسا سُند سلام، یِم خداوند سٕندِس مَنٛز محنت کران چھِ۔ پیاری پرسِس سلام، یٔمۍ رب سٕندِس سٍتـ̡ واریاہ محنت۔\n13.\\tخدایس منز منتخب کرنہٕ آمُت روفس تہٕ تسٕنزِ ماجہ تہٕ میانہِ ماجہ سٍتـ̡ سلام۔\n14. اسینکریٹس ، فلیگون ، ہرماس ، پیٹروباس ، ہرمیس تہٕ تمن سٍتـ̡ بٲے سلام۔\n15. فلولوگس، تہٕ جولیا، نیریئس تہٕ تٔمۍ سٕنزِ بینہِ، تہٕ اولمپاس تہٕ تِمن سارِنٕے سنتن سلام۔\n16. اکھ أکِس مقدس بوسہ دِتھ سلام۔ مسیح سٕندِ کلیساہس چِھ تۅہہِ سلام۔\n17. وۅنۍ چُھس بہٕ ژےٚ التجا کران زِ تِمن ہُند نشان زد کٔرِو یِم تِمن ہٕندِس عقیدس برعکس تقسیم تہٕ جُرمُک سبب بنان چھِ۔ تہٕ تِمن نِش بچُن۔\n18. یِم یِتھٕ پٲٹھۍ چھِ تِم چھِ نہٕ سٲنِس آغہٕ عیسیٰ مسیحٕچ خدمت کران بلکہِ پننِس یٔڈ سٕنزِ خدمت کران۔ تہٕ اصل کلامَو تہٕ منصفانہٕ تقریرٕ سٍتۍ چھِ سادٕ لوٗکن ہٕندِس دِلس دھوکہٕ دِوان۔\n19. تُہٕنٛز فرمانبرداری چھے سارِنٕے {انسانَن} ہٕندِ خٲطرٕ نیبرِم۔ بہٕ چُھس چانہِ طرفہٕ خوشی: مگر توتہِ چُھس بہٕ ژٕ عقلمند روزُن یُس اصل تہٕ بدی متعلق سادٕ چھُ۔ {سادٕ: یا، بے ضرر}\n20. تہٕ امنُک خدایہ کرِ شیطان تہندِس کھورَن تَل زخم۔ سٲنِس آغہٕ عیسیٰ مسیح سُند فضل چُھہ توے سٍتـ̡ ۔ آمین۔ {زخم: یا، ٹریڈ}\n21. تیموتھیئس میون ورک فیلو، تہٕ لوسیئس، تہٕ جیسن، تہٕ سوسیپیٹر، میانین رشتہٕ دار، چُھ ژے سلام۔\n22. بہٕ چُھس ٹیرٹیئس، یُس {یہِ} خط لیوکھمُت، چُھہ خداوند سٍتـ̡ سلام۔\n23. گیئس، میٲنۍ میزبان، تہٕ پورٕ کلیساہُک چُھ، چُھہ تۅہہِ سلام۔ شہرُک چیمبرلین ایراسٹس چُھ تۅہہِ سلام، تہٕ کوارٹس چُھ اکھ بٲے۔\n24. سٲنـ̡ خداوند عیسیٰ مسیح سُند فضل {ہو} چُھہ تُہۍ سارِنٕے سٍتـ̡ سٍتـ̡ آمین۔\n25. وُنہِ چُھہ تٔمِس سٍتـ̡ یُس میانہِ انجیل مُطٲبق تہٕ عیسیٰ مسیح سٕنزِ تبلیغ مُطٲبق تہٕ یُس دُنیا شروع گژھنہٕ پیٹھٕ راز تھاونہٕ آمُت اوس،\n26. مگر وُنہِ چُھ ظٲہر سپدان تہٕ پیغمبرن ہٕندِس صحیفہٕ سٍتـ̡ چُھہ ابدی خدایہ سٕندِ حُکمس مطٲبق، یُس سارنٕے قومن خٲطرٕ ایمان ہٕنزِ فرمانبرداری خٲطرٕ زاننہٕ آمُت چُھ:\n27. خدایہ سٕندِ خٲطرٕ کُنہِ حکیم، حضرت عیسیٰ مسیح سٕندِ ذریعہٕ روزُن ہمیشہٕ خٲطرٕ۔ آمین۔ «{کورنتھس پیٹھہٕ رومین لیکھنہٕ آمُت، تہٕ سوزنہٕ آمُت} سینکریا کِس چرچُک فیبی خادم سٕندِ طرفہٕ۔}»"];
